/* Source Module: src/core/module.c                                           */
/* ========================================================================= */

/**
 * ntksh - Native Module and Extension System
 * Copyright (C) 2023-2026 PC/OpenSystems LLC. All rights reserved.
 * Licensed under the terms of the BSD-3 Clause License.
 *
 * Implements:
 * 1. Native C/C++ dynamic library plugin loading (.dll) via Win32 LoadLibraryW.
 * 2. Shell script package importing (.ksh / .kshm) from KSH_MODULE_PATH.
 * 3. Modern 'module load / unload / import / list' command interface.
 * 4. Classic AT&T ksh93 'builtin -f <file.dll> [cmd]' and 'builtin -d <cmd>' interface.
 */

#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <wchar.h>
#include <stdbool.h>


#define MAX_DYNAMIC_BUILTINS 256
#define MAX_LOADED_MODULES   128

typedef struct DynamicBuiltinEntry {
    wchar_t name[64];
    KshBuiltinFn fn;
    wchar_t help[256];
    HMODULE ownerModule;
} DynamicBuiltinEntry;

typedef struct LoadedNativeModule {
    wchar_t name[128];
    wchar_t path[MAX_PATH];
    HMODULE hModule;
    KshModuleFiniFn finiFn;
} LoadedNativeModule;

typedef struct LoadedScriptModule {
    wchar_t name[128];
    wchar_t path[MAX_PATH];
} LoadedScriptModule;

static IShell* s_shell = NULL;
static DynamicBuiltinEntry s_dynamicBuiltins[MAX_DYNAMIC_BUILTINS];
static size_t s_dynamicBuiltinCount = 0;

static LoadedNativeModule s_nativeModules[MAX_LOADED_MODULES];
static size_t s_nativeModuleCount = 0;

static LoadedScriptModule s_scriptModules[MAX_LOADED_MODULES];
static size_t s_scriptModuleCount = 0;

static HMODULE s_currentlyLoadingDll = NULL;

/* ------------------------------------------------------------------------- */
/* KshPluginApi Implementation (vtable exposed to native DLL modules)        */
/* ------------------------------------------------------------------------- */

static bool Plugin_RegisterBuiltin(const wchar_t* name, KshBuiltinFn fn, const wchar_t* help_summary) {
    if (!name || !name[0] || !fn) return false;
    if (s_dynamicBuiltinCount >= MAX_DYNAMIC_BUILTINS) return false;

    /* Check if already registered */
    for (size_t i = 0; i < s_dynamicBuiltinCount; i++) {
        if (_wcsicmp(s_dynamicBuiltins[i].name, name) == 0) {
            /* Update existing */
            s_dynamicBuiltins[i].fn = fn;
            if (help_summary) {
                wcscpy_s(s_dynamicBuiltins[i].help, _countof(s_dynamicBuiltins[i].help), help_summary);
            }
            s_dynamicBuiltins[i].ownerModule = s_currentlyLoadingDll;
            return true;
        }
    }

    DynamicBuiltinEntry* entry = &s_dynamicBuiltins[s_dynamicBuiltinCount++];
    wcscpy_s(entry->name, _countof(entry->name), name);
    entry->fn = fn;
    if (help_summary) {
        wcscpy_s(entry->help, _countof(entry->help), help_summary);
    } else {
        entry->help[0] = L'\0';
    }
    entry->ownerModule = s_currentlyLoadingDll;
    return true;
}

static bool Plugin_UnregisterBuiltin(const wchar_t* name) {
    if (!name || !name[0]) return false;
    for (size_t i = 0; i < s_dynamicBuiltinCount; i++) {
        if (_wcsicmp(s_dynamicBuiltins[i].name, name) == 0) {
            for (size_t k = i; k + 1 < s_dynamicBuiltinCount; k++) {
                s_dynamicBuiltins[k] = s_dynamicBuiltins[k + 1];
            }
            s_dynamicBuiltinCount--;
            return true;
        }
    }
    return false;
}

static const wchar_t* Plugin_GetVariable(const wchar_t* name) {
    if (!name || !s_shell || !s_shell->env) return NULL;
    return s_shell->env->Get(s_shell->env, name);
}

static bool Plugin_SetVariable(const wchar_t* name, const wchar_t* value) {
    if (!name || !s_shell || !s_shell->env) return false;
    return s_shell->env->Set(s_shell->env, name, value ? value : L"");
}

static int Plugin_Eval(const wchar_t* cmdline) {
    if (!cmdline || !s_shell || !s_shell->ExecuteLine) return -1;
    return s_shell->ExecuteLine(s_shell, cmdline);
}

static void Plugin_Print(const wchar_t* fmt, ...) {
    if (!fmt) return;
    va_list ap;
    va_start(ap, fmt);
    vwprintf(fmt, ap);
    va_end(ap);
}

static void Plugin_PrintError(const wchar_t* fmt, ...) {
    if (!fmt) return;
    va_list ap;
    va_start(ap, fmt);
    vfwprintf(stderr, fmt, ap);
    va_end(ap);
}

static const KshPluginApi s_pluginApi = {
    KSH_MODULE_API_VERSION,
    Plugin_RegisterBuiltin,
    Plugin_UnregisterBuiltin,
    Plugin_GetVariable,
    Plugin_SetVariable,
    Plugin_Eval,
    Plugin_Print,
    Plugin_PrintError
};

/* ------------------------------------------------------------------------- */
/* Module Lifecycle Functions                                                */
/* ------------------------------------------------------------------------- */

bool Module_Init(IShell* shell) {
    s_shell = shell;
    return true;
}

void Module_Cleanup(void) {
    /* Invoke cleanup on all loaded native modules and free libraries */
    for (size_t i = 0; i < s_nativeModuleCount; i++) {
        if (s_nativeModules[i].finiFn) {
            s_nativeModules[i].finiFn();
        }
        if (s_nativeModules[i].hModule) {
            FreeLibrary(s_nativeModules[i].hModule);
        }
    }
    s_nativeModuleCount = 0;
    s_dynamicBuiltinCount = 0;
    s_scriptModuleCount = 0;
}

bool Module_IsDynamicBuiltin(const wchar_t* name) {
    if (!name) return false;
    for (size_t i = 0; i < s_dynamicBuiltinCount; i++) {
        if (_wcsicmp(s_dynamicBuiltins[i].name, name) == 0) {
            return true;
        }
    }
    return false;
}

bool Module_ExecDynamicBuiltin(CommandAST* cmd, int* code) {
    if (!cmd || cmd->argc < 1) return false;
    for (size_t i = 0; i < s_dynamicBuiltinCount; i++) {
        if (_wcsicmp(s_dynamicBuiltins[i].name, cmd->argv[0]) == 0) {
            return s_dynamicBuiltins[i].fn(cmd, code);
        }
    }
    return false;
}

size_t Module_GetDynamicBuiltinNames(const wchar_t* names[], size_t max_count) {
    size_t count = (s_dynamicBuiltinCount < max_count) ? s_dynamicBuiltinCount : max_count;
    for (size_t i = 0; i < count; i++) {
        names[i] = s_dynamicBuiltins[i].name;
    }
    return count;
}

/* ------------------------------------------------------------------------- */
/* Native Module Loading & Unloading                                         */
/* ------------------------------------------------------------------------- */

bool Module_LoadNative(const wchar_t* path, const wchar_t* alias_cmd, wchar_t* err_buf, size_t err_cap) {
    if (!path || !path[0]) {
        if (err_buf && err_cap) swprintf_s(err_buf, err_cap, L"missing module path");
        return false;
    }

    /* Check if module is already loaded */
    for (size_t i = 0; i < s_nativeModuleCount; i++) {
        if (_wcsicmp(s_nativeModules[i].path, path) == 0 || _wcsicmp(s_nativeModules[i].name, path) == 0) {
            if (err_buf && err_cap) swprintf_s(err_buf, err_cap, L"module already loaded: %ls", path);
            return true; /* idempotent success */
        }
    }

    if (s_nativeModuleCount >= MAX_LOADED_MODULES) {
        if (err_buf && err_cap) swprintf_s(err_buf, err_cap, L"maximum loaded module limit reached");
        return false;
    }

    wchar_t resolvedPath[MAX_PATH];
    DWORD pathLen = GetFullPathNameW(path, _countof(resolvedPath), resolvedPath, NULL);
    if (pathLen == 0 || pathLen >= _countof(resolvedPath)) {
        if (wcslen(path) >= _countof(resolvedPath)) {
            if (err_buf && err_cap) swprintf_s(err_buf, err_cap, L"module path too long");
            return false;
        }
        wcscpy_s(resolvedPath, _countof(resolvedPath), path);
    }

    HMODULE hMod = LoadLibraryW(resolvedPath);
    if (!hMod) {
        /* Try relative to module search path */
        hMod = LoadLibraryW(path);
    }
    if (!hMod) {
        DWORD err = GetLastError();
        if (err_buf && err_cap) {
            swprintf_s(err_buf, err_cap, L"LoadLibrary failed (error %lu): %ls", err, resolvedPath);
        }
        return false;
    }

    s_currentlyLoadingDll = hMod;

    /* Check for ksh_module_init entry point */
    KshModuleInitFn initFn = (KshModuleInitFn)GetProcAddress(hMod, "ksh_module_init");
    KshModuleFiniFn finiFn = (KshModuleFiniFn)GetProcAddress(hMod, "ksh_module_fini");

    bool loadedSuccessfully = false;

    if (initFn) {
        int initRes = initFn(&s_pluginApi);
        if (initRes == KSH_MODULE_SUCCESS) {
            loadedSuccessfully = true;
        } else {
            if (err_buf && err_cap) {
                swprintf_s(err_buf, err_cap, L"module initialization returned error code %d", initRes);
            }
        }
    }

    if (alias_cmd && alias_cmd[0] && !Module_IsDynamicBuiltin(alias_cmd)) {
        if (wcslen(alias_cmd) > 64) {
            if (err_buf && err_cap) swprintf_s(err_buf, err_cap, L"alias command name too long");
            FreeLibrary(hMod);
            return false;
        }
        /* Classic ksh93 builtin -f fallback: look for b_<cmd>, ksh_builtin_<cmd>, Builtin_<cmd>, or <cmd> */
        char symName[128];
        sprintf_s(symName, sizeof(symName), "b_%ls", alias_cmd);
        KshBuiltinFn bfn = (KshBuiltinFn)GetProcAddress(hMod, symName);
        if (!bfn) {
            sprintf_s(symName, sizeof(symName), "ksh_builtin_%ls", alias_cmd);
            bfn = (KshBuiltinFn)GetProcAddress(hMod, symName);
        }
        if (!bfn) {
            sprintf_s(symName, sizeof(symName), "Builtin_%ls", alias_cmd);
            bfn = (KshBuiltinFn)GetProcAddress(hMod, symName);
        }
        if (!bfn) {
            sprintf_s(symName, sizeof(symName), "%ls", alias_cmd);
            bfn = (KshBuiltinFn)GetProcAddress(hMod, symName);
        }

        if (bfn) {
            Plugin_RegisterBuiltin(alias_cmd, bfn, L"Native ksh93 extension command");
            loadedSuccessfully = true;
        } else if (!initFn) {
            if (err_buf && err_cap) {
                swprintf_s(err_buf, err_cap, L"entry point not found: b_%ls or ksh_builtin_%ls", alias_cmd, alias_cmd);
            }
        }
    } else if (!initFn && !loadedSuccessfully) {
        if (err_buf && err_cap) {
            swprintf_s(err_buf, err_cap, L"module %ls does not export ksh_module_init", path);
        }
    }

    s_currentlyLoadingDll = NULL;

    if (!loadedSuccessfully) {
        FreeLibrary(hMod);
        return false;
    }

    /* Extract module base name */
    const wchar_t* pName = wcsrchr(resolvedPath, L'\\');
    if (!pName) pName = wcsrchr(resolvedPath, L'/');
    pName = pName ? pName + 1 : resolvedPath;

    LoadedNativeModule* entry = &s_nativeModules[s_nativeModuleCount++];
    wcscpy_s(entry->name, _countof(entry->name), pName);
    wcscpy_s(entry->path, _countof(entry->path), resolvedPath);
    entry->hModule = hMod;
    entry->finiFn = finiFn;

    return true;
}

bool Module_UnloadNative(const wchar_t* name_or_path) {
    if (!name_or_path || !name_or_path[0]) return false;

    /* Extract bare filename without path for comparison */
    const wchar_t* base = wcsrchr(name_or_path, L'\\');
    const wchar_t* slash2 = wcsrchr(name_or_path, L'/');
    if (slash2 && (!base || slash2 > base)) base = slash2;
    base = base ? (base + 1) : name_or_path;

    wchar_t withDll[MAX_PATH];
    swprintf_s(withDll, _countof(withDll), L"%ls.dll", base);

    for (size_t i = 0; i < s_nativeModuleCount; i++) {
        if (_wcsicmp(s_nativeModules[i].name, name_or_path) == 0 ||
            _wcsicmp(s_nativeModules[i].name, base) == 0 ||
            _wcsicmp(s_nativeModules[i].name, withDll) == 0 ||
            _wcsicmp(s_nativeModules[i].path, name_or_path) == 0) {

            HMODULE hMod = s_nativeModules[i].hModule;

            /* Call module cleanup */
            if (s_nativeModules[i].finiFn) {
                s_nativeModules[i].finiFn();
            }

            /* Unregister all built-ins owned by this module */
            for (size_t b = 0; b < s_dynamicBuiltinCount; ) {
                if (s_dynamicBuiltins[b].ownerModule == hMod) {
                    for (size_t k = b; k + 1 < s_dynamicBuiltinCount; k++) {
                        s_dynamicBuiltins[k] = s_dynamicBuiltins[k + 1];
                    }
                    s_dynamicBuiltinCount--;
                } else {
                    b++;
                }
            }

            FreeLibrary(hMod);

            for (size_t k = i; k + 1 < s_nativeModuleCount; k++) {
                s_nativeModules[k] = s_nativeModules[k + 1];
            }
            s_nativeModuleCount--;
            return true;
        }
    }

    /* Also check if name_or_path is the name of a dynamic builtin directly */
    return Plugin_UnregisterBuiltin(name_or_path);
}

/* ------------------------------------------------------------------------- */
/* Script Module Importing (KSH_MODULE_PATH)                                 */
/* ------------------------------------------------------------------------- */

static bool FindScriptModule(const wchar_t* modName, wchar_t* outPath, size_t outCap) {
    /* 1. Try directly if path exists */
    if (GetFileAttributesW(modName) != INVALID_FILE_ATTRIBUTES) {
        wcscpy_s(outPath, outCap, modName);
        return true;
    }

    wchar_t withExt[MAX_PATH];
    swprintf_s(withExt, _countof(withExt), L"%ls.ksh", modName);
    if (GetFileAttributesW(withExt) != INVALID_FILE_ATTRIBUTES) {
        wcscpy_s(outPath, outCap, withExt);
        return true;
    }

    swprintf_s(withExt, _countof(withExt), L"%ls.kshm", modName);
    if (GetFileAttributesW(withExt) != INVALID_FILE_ATTRIBUTES) {
        wcscpy_s(outPath, outCap, withExt);
        return true;
    }

    /* 2. Check KSH_MODULE_PATH */
    wchar_t envKshModPath[MAX_PATH * 4] = L"";
    const wchar_t* searchPath = s_shell && s_shell->env ? s_shell->env->Get(s_shell->env, L"KSH_MODULE_PATH") : NULL;
    if (!searchPath) {
        if (GetEnvironmentVariableW(L"KSH_MODULE_PATH", envKshModPath, _countof(envKshModPath)) > 0) {
            searchPath = envKshModPath;
        }
    }

    wchar_t defaultPath[MAX_PATH * 4] = L"";
    if (!searchPath) {
        wchar_t appdata[MAX_PATH] = L"";
        GetEnvironmentVariableW(L"APPDATA", appdata, _countof(appdata));
        swprintf_s(defaultPath, _countof(defaultPath), L".;%ls\\ksh\\modules;C:\\ProgramData\\ksh\\modules", appdata);
        searchPath = defaultPath;
    }

    wchar_t pathCopy[MAX_PATH * 4];
    wcscpy_s(pathCopy, _countof(pathCopy), searchPath);

    wchar_t* context = NULL;
    wchar_t* token = wcstok_s(pathCopy, L";", &context);
    while (token) {
        /* try dir/modName.ksh */
        swprintf_s(outPath, outCap, L"%ls\\%ls.ksh", token, modName);
        if (GetFileAttributesW(outPath) != INVALID_FILE_ATTRIBUTES) return true;

        /* try dir/modName.kshm */
        swprintf_s(outPath, outCap, L"%ls\\%ls.kshm", token, modName);
        if (GetFileAttributesW(outPath) != INVALID_FILE_ATTRIBUTES) return true;

        /* try dir/modName/modName.ksh */
        swprintf_s(outPath, outCap, L"%ls\\%ls\\%ls.ksh", token, modName, modName);
        if (GetFileAttributesW(outPath) != INVALID_FILE_ATTRIBUTES) return true;

        token = wcstok_s(NULL, L";", &context);
    }

    return false;
}

bool Module_ImportScript(IShell* shell, const wchar_t* module_name, wchar_t* err_buf, size_t err_cap) {
    if (!module_name || !module_name[0] || !shell) return false;

    /* Check if already imported */
    for (size_t i = 0; i < s_scriptModuleCount; i++) {
        if (_wcsicmp(s_scriptModules[i].name, module_name) == 0) {
            return true; /* idempotent */
        }
    }

    wchar_t resolvedPath[MAX_PATH];
    if (!FindScriptModule(module_name, resolvedPath, _countof(resolvedPath))) {
        if (err_buf && err_cap) {
            swprintf_s(err_buf, err_cap, L"module not found in KSH_MODULE_PATH: %ls", module_name);
        }
        return false;
    }

    /* Execute the script in current shell context (source equivalent) */
    int rc = shell->RunScript(shell, resolvedPath);
    if (rc != 0) {
        if (err_buf && err_cap) {
            swprintf_s(err_buf, err_cap, L"module script %ls returned status %d", resolvedPath, rc);
        }
        return false;
    }

    if (s_scriptModuleCount < MAX_LOADED_MODULES) {
        LoadedScriptModule* sm = &s_scriptModules[s_scriptModuleCount++];
        wcscpy_s(sm->name, _countof(sm->name), module_name);
        wcscpy_s(sm->path, _countof(sm->path), resolvedPath);
    }

    return true;
}

/* ------------------------------------------------------------------------- */
/* Module List Query Function                                                */
/* ------------------------------------------------------------------------- */

void Module_List(void) {
    wprintf(L"LOADED NATIVE MODULES (%zu):\n", s_nativeModuleCount);
    if (s_nativeModuleCount == 0) {
        wprintf(L"  (none)\n");
    } else {
        for (size_t i = 0; i < s_nativeModuleCount; i++) {
            wprintf(L"  %-20ls %ls\n", s_nativeModules[i].name, s_nativeModules[i].path);
        }
    }

    wprintf(L"\nLOADED SCRIPT MODULES (%zu):\n", s_scriptModuleCount);
    if (s_scriptModuleCount == 0) {
        wprintf(L"  (none)\n");
    } else {
        for (size_t i = 0; i < s_scriptModuleCount; i++) {
            wprintf(L"  %-20ls %ls\n", s_scriptModules[i].name, s_scriptModules[i].path);
        }
    }

    wprintf(L"\nDYNAMICALLY REGISTERED BUILT-INS (%zu):\n", s_dynamicBuiltinCount);
    if (s_dynamicBuiltinCount == 0) {
        wprintf(L"  (none)\n");
    } else {
        for (size_t i = 0; i < s_dynamicBuiltinCount; i++) {
            wprintf(L"  %-16ls %ls\n", s_dynamicBuiltins[i].name,
                    s_dynamicBuiltins[i].help[0] ? s_dynamicBuiltins[i].help : L"(no description)");
        }
    }
}

/* ------------------------------------------------------------------------- */
/* 1. BUILTIN Command: ksh93 Dynamic Builtin Loader & Manager                */
/* ------------------------------------------------------------------------- */

bool Builtin_Builtin(IShell* shell, CommandAST* cmd, int* code) {
    if (cmd->argc < 2 || _wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0) {
        wprintf(L"Usage: builtin [-f lib.dll] [name]\n"
                L"       builtin -d name\n"
                L"       builtin -s\n"
                L"Add, delete, or list shell built-in commands (AT&T ksh93 builtin).\n\n"
                L"  -f lib.dll    Load dynamic built-in from Windows DLL module\n"
                L"  -d name       Delete / unload a dynamically loaded built-in command\n"
                L"  -s            Print all registered built-in command names\n");
        *code = 0;
        return true;
    }

    if (wcscmp(cmd->argv[1], L"-s") == 0 || cmd->argc == 1) {
        Module_List();
        *code = 0;
        return true;
    }

    if (wcscmp(cmd->argv[1], L"-f") == 0) {
        if (cmd->argc < 3) {
            fwprintf(stderr, L"builtin: -f requires dynamic library path\n");
            *code = 1;
            return true;
        }
        const wchar_t* dllPath = cmd->argv[2];
        const wchar_t* cmdName = (cmd->argc > 3) ? cmd->argv[3] : NULL;

        wchar_t errBuf[256] = L"";
        if (!Module_LoadNative(dllPath, cmdName, errBuf, _countof(errBuf))) {
            fwprintf(stderr, L"builtin: cannot load %ls: %ls\n", dllPath, errBuf);
            *code = 1;
            return true;
        }
        *code = 0;
        return true;
    }

    if (wcscmp(cmd->argv[1], L"-d") == 0) {
        if (cmd->argc < 3) {
            fwprintf(stderr, L"builtin: -d requires command name\n");
            *code = 1;
            return true;
        }
        if (!Module_UnloadNative(cmd->argv[2])) {
            fwprintf(stderr, L"builtin: %ls: not a dynamic built-in\n", cmd->argv[2]);
            *code = 1;
            return true;
        }
        *code = 0;
        return true;
    }

    /* Execute the builtin command directly, bypassing aliases and functions */
    CommandAST subCmd;
    memset(&subCmd, 0, sizeof(subCmd));
    subCmd.argc = cmd->argc - 1;
    for (int i = 0; i < subCmd.argc && i < 255; i++) {
        subCmd.argv[i] = cmd->argv[i + 1];
    }
    subCmd.argv[subCmd.argc] = NULL;
    return TryExecBuiltin(shell, &subCmd, code);
}

/* ------------------------------------------------------------------------- */
/* 2. MODULE Command: Modern Shell Extension Manager                         */
/* ------------------------------------------------------------------------- */

bool Builtin_Module(IShell* shell, CommandAST* cmd, int* code) {
    if (cmd->argc < 2 || _wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0 || wcscmp(cmd->argv[1], L"help") == 0) {
        wprintf(L"Usage: module <command> [arguments]\n"
                L"Manage dynamic native DLL extensions and shell script packages.\n\n"
                L"Commands:\n"
                L"  load <file.dll> [cmd]   Load a native Windows dynamic library extension\n"
                L"  unload <name>           Unload a dynamic module or built-in\n"
                L"  import <name>           Import a shell package (.ksh) from KSH_MODULE_PATH\n"
                L"  list                    List all loaded modules and dynamic built-ins\n");
        *code = (cmd->argc < 2) ? 0 : 0;
        return true;
    }

    const wchar_t* sub = cmd->argv[1];

    if (_wcsicmp(sub, L"list") == 0) {
        Module_List();
        *code = 0;
        return true;
    }

    if (_wcsicmp(sub, L"load") == 0) {
        if (cmd->argc < 3) {
            fwprintf(stderr, L"module load: missing path to DLL module\n");
            *code = 1;
            return true;
        }
        const wchar_t* dllPath = cmd->argv[2];
        const wchar_t* cmdName = (cmd->argc > 3) ? cmd->argv[3] : NULL;

        wchar_t errBuf[256] = L"";
        if (!Module_LoadNative(dllPath, cmdName, errBuf, _countof(errBuf))) {
            fwprintf(stderr, L"module: failed to load %ls: %ls\n", dllPath, errBuf);
            *code = 1;
            return true;
        }
        wprintf(L"Module loaded successfully: %ls\n", dllPath);
        *code = 0;
        return true;
    }

    if (_wcsicmp(sub, L"unload") == 0) {
        if (cmd->argc < 3) {
            fwprintf(stderr, L"module unload: missing module or built-in name\n");
            *code = 1;
            return true;
        }
        if (!Module_UnloadNative(cmd->argv[2])) {
            fwprintf(stderr, L"module: %ls: not loaded\n", cmd->argv[2]);
            *code = 1;
            return true;
        }
        wprintf(L"Module unloaded: %ls\n", cmd->argv[2]);
        *code = 0;
        return true;
    }

    if (_wcsicmp(sub, L"import") == 0) {
        if (cmd->argc < 3) {
            fwprintf(stderr, L"module import: missing module name\n");
            *code = 1;
            return true;
        }
        wchar_t errBuf[256] = L"";
        if (!Module_ImportScript(shell, cmd->argv[2], errBuf, _countof(errBuf))) {
            fwprintf(stderr, L"module: failed to import %ls: %ls\n", cmd->argv[2], errBuf);
            *code = 1;
            return true;
        }
        *code = 0;
        return true;
    }

    fwprintf(stderr, L"module: unknown command '%ls'. Use 'module help' for usage.\n", sub);
    *code = 1;
    return true;
}

/* ========================================================================= */
/* Source Module: src/batch/batch_expand.c                                    */
/* ========================================================================= */


bool Batch_Append(wchar_t** output, size_t* length,
    size_t* capacity, const wchar_t* value, size_t valueLength) {
    if (valueLength > SIZE_MAX - *length - 1) return false;
    size_t needed = *length + valueLength + 1;
    if (needed > *capacity) {
        size_t nextCapacity = *capacity ? *capacity : 256;
        while (nextCapacity < needed) {
            if (nextCapacity > SIZE_MAX / 2) return false;
            nextCapacity *= 2;
        }
        wchar_t* resized = (wchar_t*)realloc(*output,
            nextCapacity * sizeof(wchar_t));
        if (!resized) return false;
        *output = resized;
        *capacity = nextCapacity;
    }
    memcpy(*output + *length, value, valueLength * sizeof(wchar_t));
    *length += valueLength;
    (*output)[*length] = L'\0';
    return true;
}

BatchLoopVariable* Batch_FindLoopVariable(BatchContext* context,
    wchar_t name) {
    for (BatchLoopVariable* variable = context->loopVariables; variable;
        variable = variable->next) {
        if (towupper(variable->name) == towupper(name)) return variable;
    }
    return NULL;
}

const wchar_t* Batch_GetVariable(IShell* shell,
    BatchContext* context, const wchar_t* name, wchar_t* scratch,
    size_t scratchCapacity) {
    if (_wcsicmp(name, L"ERRORLEVEL") == 0) {
        _snwprintf_s(scratch, scratchCapacity, _TRUNCATE, L"%d",
            context ? context->errorLevel : shell->last_status);
        return scratch;
    }
    if (_wcsicmp(name, L"CD") == 0) {
        DWORD length = GetCurrentDirectoryW((DWORD)scratchCapacity, scratch);
        return length && length < scratchCapacity ? scratch : L"";
    }
    if (_wcsicmp(name, L"RANDOM") == 0) {
        _snwprintf_s(scratch, scratchCapacity, _TRUNCATE, L"%u",
            (unsigned int)(rand() % 32768));
        return scratch;
    }
    if (_wcsicmp(name, L"DATE") == 0 || _wcsicmp(name, L"TIME") == 0) {
        SYSTEMTIME now;
        GetLocalTime(&now);
        if (_wcsicmp(name, L"DATE") == 0)
            _snwprintf_s(scratch, scratchCapacity, _TRUNCATE,
                L"%02u/%02u/%04u", now.wMonth, now.wDay, now.wYear);
        else
            _snwprintf_s(scratch, scratchCapacity, _TRUNCATE,
                L"%02u:%02u:%02u.%02u", now.wHour, now.wMinute,
                now.wSecond, now.wMilliseconds / 10);
        return scratch;
    }
    const wchar_t* value = shell->env->Get(shell->env, name);
    if (value) return value;
    return NULL;
}

bool Batch_ApplyModifiers(IShell* shell, const wchar_t* value,
    const wchar_t* modifiers, const wchar_t* searchVariable,
    wchar_t* output, size_t outputCapacity) {
    wchar_t path[MAX_PATH * 2];
    size_t valueLength = wcslen(value);
    if (valueLength >= _countof(path)) return false;
    if (valueLength >= 2 && value[0] == L'"' &&
        value[valueLength - 1] == L'"') {
        memcpy(path, value + 1, (valueLength - 2) * sizeof(wchar_t));
        path[valueLength - 2] = L'\0';
    } else {
        wcscpy_s(path, _countof(path), value);
    }
    if (!path[0]) {
        output[0] = L'\0';
        return true;
    }
    if (searchVariable) {
        const wchar_t* searchPath = shell->env->Get(shell->env,
            searchVariable);
        wchar_t* inherited = searchPath ? NULL :
            GetEnvironmentValue(searchVariable);
        if (!searchPath) searchPath = inherited;
        wchar_t foundPath[MAX_PATH * 2];
        DWORD length = searchPath && *searchPath ?
            SearchPathW(searchPath, path, NULL, _countof(foundPath),
                foundPath, NULL) : 0;
        free(inherited);
        if (!length || length >= _countof(foundPath)) {
            output[0] = L'\0';
            return true;
        }
        wcscpy_s(path, _countof(path), foundPath);
    }
    if (wcschr(modifiers, L'f')) {
        wchar_t fullPath[MAX_PATH * 2];
        DWORD length = GetFullPathNameW(path, _countof(fullPath), fullPath,
            NULL);
        if (!length || length >= _countof(fullPath)) return false;
        wcscpy_s(path, _countof(path), fullPath);
    }
    if (wcschr(modifiers, L's')) {
        wchar_t shortPath[MAX_PATH * 2];
        DWORD length = GetShortPathNameW(path, shortPath,
            (DWORD)_countof(shortPath));
        if (length && length < _countof(shortPath))
            wcscpy_s(path, _countof(path), shortPath);
    }
    wchar_t drive[_MAX_DRIVE], directory[_MAX_DIR];
    wchar_t name[_MAX_FNAME], extension[_MAX_EXT];
    if (_wsplitpath_s(path, drive, _countof(drive), directory,
            _countof(directory), name, _countof(name), extension,
            _countof(extension)) != 0)
        return false;
    output[0] = L'\0';
    size_t used = 0;
    if (wcschr(modifiers, L'd')) {
        size_t length = wcslen(drive);
        if (length >= outputCapacity) return false;
        wcscpy_s(output, outputCapacity, drive);
        used = length;
    }
    if (wcschr(modifiers, L'p')) {
        size_t length = wcslen(directory);
        if (length >= outputCapacity - used) return false;
        wcscpy_s(output + used, outputCapacity - used, directory);
        used += length;
    }
    if (wcschr(modifiers, L'n')) {
        size_t length = wcslen(name);
        if (length >= outputCapacity - used) return false;
        wcscpy_s(output + used, outputCapacity - used, name);
        used += length;
    }
    if (wcschr(modifiers, L'x')) {
        size_t length = wcslen(extension);
        if (length >= outputCapacity - used) return false;
        wcscpy_s(output + used, outputCapacity - used, extension);
        used += length;
    }
    WIN32_FILE_ATTRIBUTE_DATA data;
    bool hasMetadata = wcschr(modifiers, L'a') || wcschr(modifiers, L't') ||
        wcschr(modifiers, L'z');
    bool hasFileData = hasMetadata &&
        GetFileAttributesExW(path, GetFileExInfoStandard, &data);
    if (wcschr(modifiers, L'a')) {
        static const struct {
            DWORD flag;
            wchar_t code;
        } attributeCodes[] = {
            { FILE_ATTRIBUTE_DIRECTORY, L'd' },
            { FILE_ATTRIBUTE_READONLY, L'r' },
            { FILE_ATTRIBUTE_HIDDEN, L'h' },
            { FILE_ATTRIBUTE_SYSTEM, L's' },
            { FILE_ATTRIBUTE_ARCHIVE, L'a' },
            { FILE_ATTRIBUTE_REPARSE_POINT, L'l' },
            { FILE_ATTRIBUTE_COMPRESSED, L'c' },
            { FILE_ATTRIBUTE_ENCRYPTED, L'e' },
            { FILE_ATTRIBUTE_OFFLINE, L'o' },
            { FILE_ATTRIBUTE_NOT_CONTENT_INDEXED, L'i' },
            { FILE_ATTRIBUTE_TEMPORARY, L't' }
        };
        for (size_t i = 0; i < _countof(attributeCodes); ++i) {
            if (used + 1 >= outputCapacity) return false;
            output[used++] = hasFileData &&
                (data.dwFileAttributes & attributeCodes[i].flag) ?
                attributeCodes[i].code : L'-';
        }
        output[used] = L'\0';
    }
    if (wcschr(modifiers, L't') && hasFileData) {
        FILETIME localTime;
        SYSTEMTIME modified;
        wchar_t date[128], time[128];
        if (FileTimeToLocalFileTime(&data.ftLastWriteTime, &localTime) &&
            FileTimeToSystemTime(&localTime, &modified) &&
            GetDateFormatW(LOCALE_USER_DEFAULT, DATE_SHORTDATE, &modified,
                NULL, date, _countof(date)) &&
            GetTimeFormatW(LOCALE_USER_DEFAULT, 0, &modified, NULL, time,
                _countof(time))) {
            int written = swprintf_s(output + used, outputCapacity - used,
                L"%ls %ls", date, time);
            if (written < 0) return false;
            used += (size_t)written;
        }
    }
    if (wcschr(modifiers, L'z') && hasFileData) {
        unsigned long long size =
            ((unsigned long long)data.nFileSizeHigh << 32) |
            data.nFileSizeLow;
        int written = swprintf_s(output + used, outputCapacity - used,
            L"%llu", size);
        if (written < 0) return false;
        used += (size_t)written;
    }
    if (!used) {
        if (wcslen(path) >= outputCapacity) return false;
        wcscpy_s(output, outputCapacity, path);
    }
    return true;
}

/*
 * CMD expands a batch line in two phases: %VAR%/argument expansion happens
 * once when the line (or parenthesized block) is read, while FOR variables,
 * delayed !VAR! expansion and caret escapes are resolved per command.
 */


static const wchar_t* Batch_FindInsensitive(const wchar_t* text,
    const wchar_t* needle) {
    size_t needleLength = wcslen(needle);
    if (!needleLength) return NULL;
    for (; *text; ++text) {
        if (_wcsnicmp(text, needle, needleLength) == 0) return text;
    }
    return NULL;
}

/* Appends NAME, NAME:~start[,length] or NAME:[*]search=replace. */
static bool Batch_AppendVariable(IShell* shell, BatchContext* context,
    const wchar_t* spec, size_t specLength, wchar_t** output,
    size_t* length, size_t* capacity) {
    wchar_t name[MAX_LINE_LEN];
    if (specLength >= _countof(name)) return false;
    memcpy(name, spec, specLength * sizeof(wchar_t));
    name[specLength] = L'\0';
    wchar_t* modifier = wcschr(name, L':');
    if (modifier) *modifier++ = L'\0';
    wchar_t scratch[MAX_PATH * 2];
    wchar_t* inherited = NULL;
    const wchar_t* value = *name ? Batch_GetVariable(shell, context, name,
        scratch, _countof(scratch)) : NULL;
    if (!value && *name) value = inherited = GetEnvironmentValue(name);
    if (!value) value = L"";
    size_t valueLength = wcslen(value);
    bool ok = true;
    if (!modifier) {
        ok = Batch_Append(output, length, capacity, value, valueLength);
    } else if (*modifier == L'~') {
        long long total = (long long)valueLength;
        wchar_t* end = NULL;
        long long start = wcstoll(modifier + 1, &end, 10);
        long long stop = total;
        if (start < 0) start += total;
        if (start < 0) start = 0;
        if (start > total) start = total;
        if (*end == L',') {
            long long count = wcstoll(end + 1, NULL, 10);
            stop = count < 0 ? total + count : start + count;
        }
        if (stop > total) stop = total;
        if (stop < start) stop = start;
        ok = Batch_Append(output, length, capacity, value + start,
            (size_t)(stop - start));
    } else {
        wchar_t* equal = wcschr(modifier, L'=');
        const wchar_t* search = modifier;
        bool firstOnly = *search == L'*';
        if (firstOnly) search++;
        if (!equal || search == equal) {
            ok = Batch_Append(output, length, capacity, value, valueLength);
        } else {
            *equal = L'\0';
            const wchar_t* replacement = equal + 1;
            size_t searchLength = wcslen(search);
            const wchar_t* cursor = value;
            const wchar_t* match;
            while (ok && (match = Batch_FindInsensitive(cursor, search))) {
                ok = (firstOnly || Batch_Append(output, length, capacity,
                        cursor, (size_t)(match - cursor))) &&
                    Batch_Append(output, length, capacity, replacement,
                        wcslen(replacement));
                cursor = match + searchLength;
                if (firstOnly) break;
            }
            ok = ok && Batch_Append(output, length, capacity, cursor,
                wcslen(cursor));
        }
    }
    free(inherited);
    return ok;
}

static const wchar_t* Batch_GetArgument(BatchContext* context,
    unsigned int index, bool resolveScript) {
    if (index == 0) {
        /* %~f0 and friends name the batch file even inside CALL :label. */
        if (resolveScript && context->batchFile) return context->batchFile;
        return context->scriptPath ? context->scriptPath : L"";
    }
    int argument = context->shift + (int)index - 1;
    if (argument >= 0 && argument < context->argumentCount &&
        context->arguments[argument])
        return context->arguments[argument];
    return L"";
}

/* Expands %%X, %%~modsX or %%~mods$VAR:X; text points just past the %%. */
static bool Batch_AppendLoopReference(IShell* shell, BatchContext* context,
    const wchar_t* text, size_t* consumed, wchar_t** output,
    size_t* length, size_t* capacity, bool* failed) {
    *failed = false;
    if (!text[0]) return false;
    if (text[0] != L'~') {
        BatchLoopVariable* variable = Batch_FindLoopVariable(context, text[0]);
        if (!variable) return false;
        const wchar_t* value = variable->value ? variable->value : L"";
        *consumed = 1;
        *failed = !Batch_Append(output, length, capacity, value,
            wcslen(value));
        return true;
    }
    size_t run = 0;
    while (run < 15 && text[1 + run] &&
        wcschr(L"fdpnxstaz", towlower(text[1 + run])))
        run++;
    /* Prefer the longest modifier run that still ends in a loop variable. */
    for (size_t k = run + 1; k-- > 0;) {
        wchar_t modifiers[16];
        for (size_t m = 0; m < k; ++m)
            modifiers[m] = (wchar_t)towlower(text[1 + m]);
        modifiers[k] = L'\0';
        const wchar_t* searchVariable = NULL;
        wchar_t searchName[256];
        size_t nameIndex = 1 + k;
        if (text[nameIndex] == L'$') {
            const wchar_t* colon = wcschr(text + nameIndex + 1, L':');
            size_t nameLength = colon ?
                (size_t)(colon - (text + nameIndex + 1)) : 0;
            if (!nameLength || nameLength >= _countof(searchName)) continue;
            memcpy(searchName, text + nameIndex + 1,
                nameLength * sizeof(wchar_t));
            searchName[nameLength] = L'\0';
            searchVariable = searchName;
            nameIndex = (size_t)(colon - text) + 1;
        }
        BatchLoopVariable* variable = text[nameIndex] ?
            Batch_FindLoopVariable(context, text[nameIndex]) : NULL;
        if (!variable) continue;
        wchar_t formatted[MAX_PATH * 2];
        *consumed = nameIndex + 1;
        *failed = !Batch_ApplyModifiers(shell,
                variable->value ? variable->value : L"", modifiers,
                searchVariable, formatted, _countof(formatted)) ||
            !Batch_Append(output, length, capacity, formatted,
                wcslen(formatted));
        return true;
    }
    return false;
}

wchar_t* Batch_Expand(IShell* shell, BatchContext* context,
    const wchar_t* input, int mode) {
    size_t capacity = 0;
    size_t length = 0;
    wchar_t* output = NULL;
    if (!Batch_Append(&output, &length, &capacity, L"", 0)) return NULL;
    bool quoted = false;
    for (size_t i = 0; input[i];) {
        wchar_t current = input[i];
        if (mode == BATCH_EXPAND_LOOP) {
            /* Only FOR variables; carets, quotes and %% stay for a child. */
            if (current == L'%' && input[i + 1] == L'%') {
                size_t consumed = 0;
                bool failed = false;
                if (Batch_AppendLoopReference(shell, context, input + i + 2,
                        &consumed, &output, &length, &capacity, &failed)) {
                    if (failed) goto fail;
                    i += 2 + consumed;
                    continue;
                }
                if (!Batch_Append(&output, &length, &capacity, input + i, 2))
                    goto fail;
                i += 2;
                continue;
            }
            if (!Batch_Append(&output, &length, &capacity, input + i, 1))
                goto fail;
            i++;
            continue;
        }
        if (mode == BATCH_EXPAND_FINAL) {
            if (current == L'"') {
                quoted = !quoted;
            } else if (current == L'\n') {
                quoted = false;
            } else if (current == L'^' && !quoted) {
                if (input[i + 1] && !Batch_Append(&output, &length,
                        &capacity, input + i + 1, 1))
                    goto fail;
                i += input[i + 1] ? 2 : 1;
                continue;
            } else if (current == L'!' && context->delayedExpansion) {
                const wchar_t* close = wcschr(input + i + 1, L'!');
                if (close) {
                    size_t nameLength = (size_t)(close - (input + i + 1));
                    if (nameLength && !Batch_AppendVariable(shell, context,
                            input + i + 1, nameLength, &output, &length,
                            &capacity))
                        goto fail;
                    i = (size_t)(close - input) + 1;
                    continue;
                }
                i++;
                continue;
            } else if (current == L'%' && input[i + 1] == L'%') {
                size_t consumed = 0;
                bool failed = false;
                if (Batch_AppendLoopReference(shell, context, input + i + 2,
                        &consumed, &output, &length, &capacity, &failed)) {
                    if (failed) goto fail;
                    i += 2 + consumed;
                    continue;
                }
                if (!Batch_Append(&output, &length, &capacity, L"%", 1))
                    goto fail;
                i += 2;
                continue;
            }
            if (!Batch_Append(&output, &length, &capacity, input + i, 1))
                goto fail;
            i++;
            continue;
        }

        if (current != L'%') {
            if (!Batch_Append(&output, &length, &capacity, input + i, 1))
                goto fail;
            i++;
            continue;
        }
        if (input[i + 1] == L'%') {
            /* Keep %% so FOR variables survive until the final phase. */
            if (!Batch_Append(&output, &length, &capacity, input + i, 2))
                goto fail;
            i += 2;
            continue;
        }
        if (input[i + 1] == L'~') {
            size_t candidate = i + 2;
            wchar_t modifiers[16];
            size_t modifierLength = 0;
            while (input[candidate] &&
                wcschr(L"fdpnxstaz", towlower(input[candidate])) &&
                modifierLength + 1 < _countof(modifiers))
                modifiers[modifierLength++] =
                    (wchar_t)towlower(input[candidate++]);
            modifiers[modifierLength] = L'\0';
            if (input[candidate] >= L'0' && input[candidate] <= L'9') {
                const wchar_t* value = Batch_GetArgument(context,
                    (unsigned int)(input[candidate] - L'0'), true);
                wchar_t formatted[MAX_PATH * 2];
                if (!Batch_ApplyModifiers(shell, value, modifiers, NULL,
                        formatted, _countof(formatted)) ||
                    !Batch_Append(&output, &length, &capacity, formatted,
                        wcslen(formatted)))
                    goto fail;
                i = candidate + 1;
                continue;
            }
        }
        if (input[i + 1] >= L'0' && input[i + 1] <= L'9') {
            const wchar_t* value = Batch_GetArgument(context,
                (unsigned int)(input[i + 1] - L'0'), false);
            if (!Batch_Append(&output, &length, &capacity, value,
                    wcslen(value)))
                goto fail;
            i += 2;
            continue;
        }
        if (input[i + 1] == L'*') {
            for (int argument = 0; argument < context->argumentCount;
                ++argument) {
                if (!context->arguments[argument]) continue;
                if (argument &&
                    !Batch_Append(&output, &length, &capacity, L" ", 1))
                    goto fail;
                if (!Batch_Append(&output, &length, &capacity,
                        context->arguments[argument],
                        wcslen(context->arguments[argument])))
                    goto fail;
            }
            i += 2;
            continue;
        }
        const wchar_t* close = wcschr(input + i + 1, L'%');
        if (close && close > input + i + 1) {
            if (!Batch_AppendVariable(shell, context, input + i + 1,
                    (size_t)(close - (input + i + 1)), &output, &length,
                    &capacity))
                goto fail;
            i = (size_t)(close - input) + 1;
            continue;
        }
        if (!Batch_Append(&output, &length, &capacity, L"%", 1))
            goto fail;
        i++;
    }
    return output;
fail:
    free(output);
    return NULL;
}


