#include <aclapi.h>
#include <time.h>
#include <math.h>

/* ========================================================================= */
/*                          BSD Core Utilities for Windows NT                */
/*      fmt, csplit, chmod, chown, jot, chflags, rs, lockf                   */
/* ========================================================================= */

/* Forward declaration of file recursion helper */
typedef void (*FileCallback)(const wchar_t* path, void* ctx);

static void RecurseDirectoryTree(const wchar_t* dirPath, FileCallback cb, void* ctx) {
    wchar_t searchPath[MAX_PATH * 2];
    swprintf(searchPath, sizeof(searchPath) / sizeof(searchPath[0]), L"%ls\\*", dirPath);

    WIN32_FIND_DATAW fd;
    HANDLE hFind = FindFirstFileW(searchPath, &fd);
    if (hFind == INVALID_HANDLE_VALUE) return;

    do {
        if (wcscmp(fd.cFileName, L".") == 0 || wcscmp(fd.cFileName, L"..") == 0)
            continue;

        wchar_t fullPath[MAX_PATH * 2];
        swprintf(fullPath, sizeof(fullPath) / sizeof(fullPath[0]), L"%ls\\%ls", dirPath, fd.cFileName);

        cb(fullPath, ctx);

        if (fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) {
            RecurseDirectoryTree(fullPath, cb, ctx);
        }
    } while (FindNextFileW(hFind, &fd));

    FindClose(hFind);
}

/* ========================================================================= */
/* 1. FMT: BSD Paragraph Formatter                                           */
/* ========================================================================= */

typedef struct {
    int max_width;
    int goal_width;
    bool crown;
    bool split_only;
    bool mail_headers;
} FmtConfig;

static bool IsHeaderLine(const wchar_t* line) {
    if (wcsncmp(line, L"From ", 5) == 0 ||
        wcsncmp(line, L">", 1) == 0 ||
        wcsncmp(line, L"#", 1) == 0)
        return true;
    const wchar_t* colon = wcschr(line, L':');
    if (colon && colon > line && (colon - line) < 30) {
        bool all_ident = true;
        for (const wchar_t* p = line; p < colon; p++) {
            if (!iswalnum(*p) && *p != L'-' && *p != L'_') {
                all_ident = false;
                break;
            }
        }
        if (all_ident) return true;
    }
    return false;
}

static size_t CountIndent(const wchar_t* s) {
    size_t count = 0;
    while (*s == L' ' || *s == L'\t') {
        count += (*s == L'\t') ? 8 : 1;
        s++;
    }
    return count;
}

static void FormatParagraph(wchar_t** lines, size_t line_count, const FmtConfig* cfg) {
    if (line_count == 0) return;

    if (cfg->split_only) {
        for (size_t i = 0; i < line_count; i++) {
            const wchar_t* p = lines[i];
            size_t ind = CountIndent(p);
            while (*p == L' ' || *p == L'\t') p++;

            while (*p) {
                size_t rem = wcslen(p);
                if ((int)(rem + ind) <= cfg->max_width) {
                    for (size_t k = 0; k < ind; k++) putwchar(L' ');
                    wprintf(L"%ls\n", p);
                    break;
                }
                int break_pos = cfg->max_width - (int)ind;
                if (break_pos <= 0) break_pos = 1;
                int space_pos = -1;
                for (int j = 0; j <= break_pos && p[j]; j++) {
                    if (iswspace(p[j])) space_pos = j;
                }
                if (space_pos > 0) {
                    for (size_t k = 0; k < ind; k++) putwchar(L' ');
                    wprintf(L"%.*ls\n", space_pos, p);
                    p += space_pos + 1;
                    while (*p == L' ') p++;
                } else {
                    for (size_t k = 0; k < ind; k++) putwchar(L' ');
                    wprintf(L"%.*ls\n", break_pos, p);
                    p += break_pos;
                }
            }
        }
        return;
    }

    size_t indent1 = CountIndent(lines[0]);
    size_t indent2 = (line_count > 1 && cfg->crown) ? CountIndent(lines[1]) : indent1;

    /* Collect words */
    size_t cap = 256, wcount = 0;
    wchar_t** words = (wchar_t**)malloc(cap * sizeof(wchar_t*));
    if (!words) return;

    for (size_t i = 0; i < line_count; i++) {
        wchar_t* p = lines[i];
        while (*p == L' ' || *p == L'\t') p++;
        while (*p) {
            while (*p && iswspace(*p)) p++;
            if (!*p) break;
            wchar_t* start = p;
            while (*p && !iswspace(*p)) p++;
            size_t wlen = p - start;
            wchar_t* word = (wchar_t*)malloc((wlen + 1) * sizeof(wchar_t));
            if (word) {
                wcsncpy(word, start, wlen);
                word[wlen] = L'\0';
                if (wcount >= cap) {
                    cap *= 2;
                    wchar_t** new_words = (wchar_t**)realloc(words, cap * sizeof(wchar_t*));
                    if (!new_words) {
                        free(word);
                        break;
                    }
                    words = new_words;
                }
                words[wcount++] = word;
            }
        }
    }

    if (wcount == 0) {
        free(words);
        return;
    }

    /* Output wrapped text */
    size_t cur_line = 0;
    size_t cur_col = (cur_line == 0) ? indent1 : indent2;
    for (size_t k = 0; k < cur_col; k++) putwchar(L' ');

    for (size_t i = 0; i < wcount; i++) {
        size_t wlen = wcslen(words[i]);
        if (cur_col + wlen + (cur_col > ((cur_line == 0) ? indent1 : indent2) ? 1 : 0) > (size_t)cfg->max_width) {
            putwchar(L'\n');
            cur_line++;
            cur_col = (cur_line == 0) ? indent1 : indent2;
            for (size_t k = 0; k < cur_col; k++) putwchar(L' ');
        } else if (cur_col > ((cur_line == 0) ? indent1 : indent2)) {
            putwchar(L' ');
            cur_col++;
        }
        wprintf(L"%ls", words[i]);
        cur_col += wlen;
        free(words[i]);
    }
    putwchar(L'\n');
    free(words);
}

static void ProcessFmtStream(FILE* fp, const FmtConfig* cfg) {
    wchar_t line[8192];
    size_t cap = 128, count = 0;
    wchar_t** para = (wchar_t**)malloc(cap * sizeof(wchar_t*));
    if (!para) return;

    while (fgetws(line, sizeof(line) / sizeof(line[0]), fp)) {
        size_t len = wcslen(line);
        while (len > 0 && (line[len - 1] == L'\r' || line[len - 1] == L'\n'))
            line[--len] = L'\0';

        /* Blank line breaks paragraph */
        if (len == 0) {
            if (count > 0) {
                FormatParagraph(para, count, cfg);
                for (size_t i = 0; i < count; i++) free(para[i]);
                count = 0;
            }
            putwchar(L'\n');
            continue;
        }

        /* Mail headers or standalone quotes */
        if (cfg->mail_headers && IsHeaderLine(line)) {
            if (count > 0) {
                FormatParagraph(para, count, cfg);
                for (size_t i = 0; i < count; i++) free(para[i]);
                count = 0;
            }
            wprintf(L"%ls\n", line);
            continue;
        }

        if (count >= cap) {
            cap *= 2;
            wchar_t** new_para = (wchar_t**)realloc(para, cap * sizeof(wchar_t*));
            if (!new_para) {
                break;
            }
            para = new_para;
        }
        wchar_t* dup = _wcsdup(line);
        if (dup) {
            para[count++] = dup;
        }
    }

    if (count > 0) {
        FormatParagraph(para, count, cfg);
        for (size_t i = 0; i < count; i++) free(para[i]);
    }
    free(para);
}

bool Builtin_Fmt(CommandAST* cmd, int* code) {
    if (cmd->argc > 1 && (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: fmt [-c] [-m] [-s] [-w width] [file ...]\n"
                L"Simple optimal text and paragraph formatter.\n\n"
                L"  -c          Crown margin (preserve indentation of first two lines)\n"
                L"  -m          Allow paragraph header lines without rejoining\n"
                L"  -s          Split lines only (do not join short lines)\n"
                L"  -w width    Set maximum display width (default: 65)\n"
                L"  -width      Numeric abbreviation for -w width\n");
        *code = 0;
        return true;
    }

    FmtConfig cfg;
    cfg.max_width = 65;
    cfg.goal_width = 55;
    cfg.crown = false;
    cfg.split_only = false;
    cfg.mail_headers = false;

    int file_start = 1;
    for (int i = 1; i < cmd->argc; i++) {
        const wchar_t* arg = cmd->argv[i];
        if (arg[0] == L'-' && arg[1] != L'\0' && wcscmp(arg, L"-") != 0) {
            if (iswdigit(arg[1])) {
                cfg.max_width = (int)wcstol(arg + 1, NULL, 10);
                if (cfg.max_width < 10) cfg.max_width = 65;
            } else if (wcscmp(arg, L"-c") == 0) {
                cfg.crown = true;
            } else if (wcscmp(arg, L"-m") == 0) {
                cfg.mail_headers = true;
            } else if (wcscmp(arg, L"-s") == 0) {
                cfg.split_only = true;
            } else if (wcscmp(arg, L"-w") == 0) {
                if (++i < cmd->argc) {
                    cfg.max_width = (int)wcstol(cmd->argv[i], NULL, 10);
                    if (cfg.max_width < 10) cfg.max_width = 65;
                }
            } else if (wcsncmp(arg, L"-w", 2) == 0) {
                cfg.max_width = (int)wcstol(arg + 2, NULL, 10);
                if (cfg.max_width < 10) cfg.max_width = 65;
            } else {
                file_start = i;
                break;
            }
            file_start = i + 1;
        } else {
            file_start = i;
            break;
        }
    }

    if (file_start >= cmd->argc) {
        ProcessFmtStream(stdin, &cfg);
    } else {
        for (int i = file_start; i < cmd->argc; i++) {
            if (wcscmp(cmd->argv[i], L"-") == 0) {
                ProcessFmtStream(stdin, &cfg);
            } else {
                FILE* fp = _wfsopen(cmd->argv[i], L"r", _SH_DENYNO);
                if (!fp) {
                    fwprintf(stderr, L"fmt: %ls: No such file or directory\n", cmd->argv[i]);
                    *code = 1;
                    continue;
                }
                ProcessFmtStream(fp, &cfg);
                fclose(fp);
            }
        }
    }

    *code = 0;
    return true;
}

/* ========================================================================= */
/* 2. CSPLIT: BSD Context Split                                              */
/* ========================================================================= */

typedef struct {
    const wchar_t* prefix;
    int digits;
    int file_num;
    wchar_t created_files[256][MAX_PATH];
    int created_count;
    bool silent;
    wchar_t** lines;
    size_t total_lines;
} CsplitWriter;

static bool CsplitWriteSection(CsplitWriter* cw, size_t from, size_t to) {
    wchar_t out_name[MAX_PATH];
    if (swprintf_s(out_name, _countof(out_name), L"%ls%0*d", cw->prefix, cw->digits, cw->file_num++) < 0) {
        return false;
    }
    FILE* out = _wfsopen(out_name, L"w", _SH_DENYWR);
    if (!out) return false;

    size_t bytes = 0;
    for (size_t l = from; l < to && l < cw->total_lines; l++) {
        fputws(cw->lines[l], out);
        bytes += wcslen(cw->lines[l]);
    }
    fclose(out);

    if (cw->created_count < 256) {
        wcscpy_s(cw->created_files[cw->created_count++], MAX_PATH, out_name);
    }
    if (!cw->silent) {
        wprintf(L"%zu\n", bytes);
    }
    return true;
}

bool Builtin_Csplit(CommandAST* cmd, int* code) {
    if (cmd->argc < 3 || (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: csplit [-k] [-s] [-f prefix] [-n digits] file arg1 [arg2 ...]\n"
                L"Split a file into sections determined by context lines.\n\n"
                L"  -f prefix   Use prefix instead of 'xx'\n"
                L"  -n digits   Use digits decimal places (default: 2)\n"
                L"  -k          Keep created files upon error\n"
                L"  -s, -q      Do not print sizes of output files\n"
                L"  Args can be: LINE_NUM, /REGEXP/[offset], %%REGEXP%%[offset], {REPEAT}\n");
        *code = (cmd->argc < 3) ? 1 : 0;
        return true;
    }

    const wchar_t* prefix = L"xx";
    int digits = 2;
    bool keep_files = false;
    bool silent = false;
    int arg_idx = 1;

    while (arg_idx < cmd->argc && cmd->argv[arg_idx][0] == L'-' && cmd->argv[arg_idx][1] != L'\0' && wcscmp(cmd->argv[arg_idx], L"-") != 0) {
        const wchar_t* opt = cmd->argv[arg_idx];
        if (wcscmp(opt, L"-k") == 0) {
            keep_files = true;
        } else if (wcscmp(opt, L"-s") == 0 || wcscmp(opt, L"-q") == 0) {
            silent = true;
        } else if (wcscmp(opt, L"-f") == 0 && arg_idx + 1 < cmd->argc) {
            prefix = cmd->argv[++arg_idx];
        } else if (wcsncmp(opt, L"-f", 2) == 0) {
            prefix = opt + 2;
        } else if (wcscmp(opt, L"-n") == 0 && arg_idx + 1 < cmd->argc) {
            digits = (int)wcstol(cmd->argv[++arg_idx], NULL, 10);
            if (digits < 1) digits = 2;
            if (digits > 16) digits = 16;
        } else if (wcsncmp(opt, L"-n", 2) == 0) {
            digits = (int)wcstol(opt + 2, NULL, 10);
            if (digits < 1) digits = 2;
            if (digits > 16) digits = 16;
        } else {
            break;
        }
        arg_idx++;
    }

    if (arg_idx >= cmd->argc) {
        fwprintf(stderr, L"csplit: missing file argument\n");
        *code = 1;
        return true;
    }

    const wchar_t* filename = cmd->argv[arg_idx++];
    FILE* fp = (wcscmp(filename, L"-") == 0) ? stdin : _wfsopen(filename, L"r", _SH_DENYNO);
    if (!fp) {
        fwprintf(stderr, L"csplit: %ls: Cannot open file\n", filename);
        *code = 1;
        return true;
    }

    /* Read all lines */
    size_t cap = 512, total_lines = 0;
    wchar_t** lines = (wchar_t**)malloc(cap * sizeof(wchar_t*));
    if (!lines) {
        if (fp != stdin) fclose(fp);
        *code = 1;
        return true;
    }
    wchar_t buf[8192];
    while (fgetws(buf, sizeof(buf) / sizeof(buf[0]), fp)) {
        if (total_lines >= cap) {
            cap *= 2;
            wchar_t** new_lines = (wchar_t**)realloc(lines, cap * sizeof(wchar_t*));
            if (!new_lines) {
                break;
            }
            lines = new_lines;
        }
        wchar_t* dup = _wcsdup(buf);
        if (dup) {
            lines[total_lines++] = dup;
        }
    }
    if (fp != stdin) fclose(fp);

    CsplitWriter cw;
    cw.prefix = prefix;
    cw.digits = digits;
    cw.file_num = 0;
    cw.created_count = 0;
    cw.silent = silent;
    cw.lines = lines;
    cw.total_lines = total_lines;

    size_t cur_line = 0;
    bool error_occurred = false;
    for (int a = arg_idx; a < cmd->argc; a++) {
        const wchar_t* pat = cmd->argv[a];
        int repeat_count = 1;
        bool repeat_inf = false;

        /* Check for repeat suffix {N} or {*} */
        if (a + 1 < cmd->argc && cmd->argv[a + 1][0] == L'{') {
            const wchar_t* rep_str = cmd->argv[a + 1];
            if (wcscmp(rep_str, L"{*}") == 0) {
                repeat_inf = true;
            } else {
                repeat_count = (int)wcstol(rep_str + 1, NULL, 10) + 1;
            }
            a++;
        }

        for (int r = 0; r < repeat_count || repeat_inf; r++) {
            if (cur_line >= total_lines) break;

            if (iswdigit(pat[0])) {
                size_t target_line = (size_t)wcstoul(pat, NULL, 10);
                if (target_line < 1) target_line = 1;
                target_line--; /* 1-indexed to 0-indexed */
                if (target_line <= cur_line || target_line > total_lines) {
                    error_occurred = true;
                    break;
                }
                if (!CsplitWriteSection(&cw, cur_line, target_line)) {
                    error_occurred = true;
                    break;
                }
                cur_line = target_line;
            } else if (pat[0] == L'/' || pat[0] == L'%') {
                bool skip_output = (pat[0] == L'%');
                wchar_t delim = pat[0];
                const wchar_t* end_delim = wcschr(pat + 1, delim);
                if (!end_delim) { error_occurred = true; break; }

                size_t re_len = end_delim - (pat + 1);
                wchar_t* re_str = (wchar_t*)malloc((re_len + 1) * sizeof(wchar_t));
                if (!re_str) { error_occurred = true; break; }
                wcsncpy(re_str, pat + 1, re_len);
                re_str[re_len] = L'\0';

                int offset = 0;
                if (*(end_delim + 1) != L'\0') {
                    offset = (int)wcstol(end_delim + 1, NULL, 10);
                }

                size_t match_line = total_lines;
                for (size_t l = cur_line; l < total_lines; l++) {
                    int off = 0, len = 0;
                    if (GrepRegexMatch(re_str, lines[l], false, false, false, &off, &len)) {
                        match_line = l;
                        break;
                    }
                }
                free(re_str);

                if (match_line == total_lines) {
                    if (repeat_inf) break;
                    error_occurred = true;
                    break;
                }

                size_t split_point = (size_t)((int)match_line + offset);
                if (split_point > total_lines) split_point = total_lines;

                if (!skip_output) {
                    if (!CsplitWriteSection(&cw, cur_line, split_point)) {
                        error_occurred = true;
                        break;
                    }
                }
                cur_line = split_point;
            }
        }

        if (error_occurred) break;
    }

    if (!error_occurred && cur_line < total_lines) {
        CsplitWriteSection(&cw, cur_line, total_lines);
    }

    /* Cleanup on error if -k was not specified */
    if (error_occurred && !keep_files) {
        for (int i = 0; i < cw.created_count; i++) {
            _wremove(cw.created_files[i]);
        }
    }

    for (size_t l = 0; l < total_lines; l++) free(lines[l]);
    free(lines);

    *code = error_occurred ? 1 : 0;
    return true;
}

/* ========================================================================= */
/* 3. CHMOD: BSD File Mode / ReadOnly Attribute Control                      */
/* ========================================================================= */

typedef struct {
    bool recursive;
    bool verbose;
    bool force;
    int octal_mode;
    wchar_t symbolic_mode[64];
    bool is_octal;
} ChmodContext;

static void ApplyChmod(const wchar_t* path, void* ctx) {
    ChmodContext* c = (ChmodContext*)ctx;
    DWORD attrs = GetFileAttributesW(path);
    if (attrs == INVALID_FILE_ATTRIBUTES) {
        if (!c->force) fwprintf(stderr, L"chmod: %ls: No such file or directory\n", path);
        return;
    }

    DWORD new_attrs = attrs;
    if (c->is_octal) {
        /* If write bits (0222) are absent, set READONLY */
        if ((c->octal_mode & 0222) == 0) {
            new_attrs |= FILE_ATTRIBUTE_READONLY;
        } else {
            new_attrs &= ~FILE_ATTRIBUTE_READONLY;
        }
    } else {
        const wchar_t* m = c->symbolic_mode;
        while (*m) {
            wchar_t op = L'\0';
            while (*m && *m != L'+' && *m != L'-' && *m != L'=') m++;
            if (!*m) break;
            op = *m++;
            bool has_w = false;
            while (*m && *m != L',') {
                if (*m == L'w') has_w = true;
                m++;
            }
            if (op == L'+' && has_w) new_attrs &= ~FILE_ATTRIBUTE_READONLY;
            else if (op == L'-' && has_w) new_attrs |= FILE_ATTRIBUTE_READONLY;
            else if (op == L'=' && !has_w) new_attrs |= FILE_ATTRIBUTE_READONLY;
            else if (op == L'=' && has_w) new_attrs &= ~FILE_ATTRIBUTE_READONLY;
            if (*m == L',') m++;
        }
    }

    if (new_attrs != attrs) {
        if (!SetFileAttributesW(path, new_attrs)) {
            if (!c->force) fwprintf(stderr, L"chmod: %ls: Failed to change mode\n", path);
            return;
        }
        if (c->verbose) {
            wprintf(L"mode of '%ls' changed to %04o\n", path, c->is_octal ? c->octal_mode : 0644);
        }
    } else if (c->verbose) {
        wprintf(L"mode of '%ls' retained\n", path);
    }
}

bool Builtin_Chmod(CommandAST* cmd, int* code) {
    if (cmd->argc < 3 || (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: chmod [-R] [-v] [-f] mode file ...\n"
                L"Change file access permissions / attributes on Windows NT.\n\n"
                L"  -R          Recursive directory processing\n"
                L"  -v          Verbose diagnostic output for each file\n"
                L"  -f          Force / suppress error diagnostics\n"
                L"  mode        Octal (e.g. 0755, 644, 444) or symbolic (+w, -w, +x, u=rw)\n");
        *code = (cmd->argc < 3) ? 1 : 0;
        return true;
    }

    ChmodContext ctx;
    ctx.recursive = false;
    ctx.verbose = false;
    ctx.force = false;
    ctx.is_octal = false;
    ctx.octal_mode = 0644;
    ctx.symbolic_mode[0] = L'\0';

    int arg_idx = 1;
    while (arg_idx < cmd->argc && cmd->argv[arg_idx][0] == L'-' &&
           !iswdigit(cmd->argv[arg_idx][1]) && cmd->argv[arg_idx][1] != L'\0') {
        const wchar_t* arg = cmd->argv[arg_idx];
        if (wcscmp(arg, L"-R") == 0) ctx.recursive = true;
        else if (wcscmp(arg, L"-v") == 0) ctx.verbose = true;
        else if (wcscmp(arg, L"-f") == 0) ctx.force = true;
        else break;
        arg_idx++;
    }

    if (arg_idx >= cmd->argc) {
        fwprintf(stderr, L"chmod: missing operand\n");
        *code = 1;
        return true;
    }

    const wchar_t* mode_str = cmd->argv[arg_idx++];
    if (iswdigit(mode_str[0])) {
        ctx.is_octal = true;
        ctx.octal_mode = (int)wcstol(mode_str, NULL, 8);
    } else {
        ctx.is_octal = false;
        wcsncpy_s(ctx.symbolic_mode, _countof(ctx.symbolic_mode), mode_str, _TRUNCATE);
    }

    for (int i = arg_idx; i < cmd->argc; i++) {
        ApplyChmod(cmd->argv[i], &ctx);
        if (ctx.recursive) {
            DWORD attr = GetFileAttributesW(cmd->argv[i]);
            if (attr != INVALID_FILE_ATTRIBUTES && (attr & FILE_ATTRIBUTE_DIRECTORY)) {
                RecurseDirectoryTree(cmd->argv[i], ApplyChmod, &ctx);
            }
        }
    }

    *code = 0;
    return true;
}

/* ========================================================================= */
/* 4. CHOWN: BSD Change File Owner / Group via Windows Security Descriptors  */
/* ========================================================================= */

typedef struct {
    bool recursive;
    bool verbose;
    bool force;
    PSID owner_sid;
    PSID group_sid;
    wchar_t owner_name[128];
    wchar_t group_name[128];
} ChownContext;

static void EnablePrivilege(LPCWSTR privName) {
    HANDLE hToken;
    if (OpenProcessToken(GetCurrentProcess(), TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY, &hToken)) {
        TOKEN_PRIVILEGES tp;
        LUID luid;
        if (LookupPrivilegeValueW(NULL, privName, &luid)) {
            tp.PrivilegeCount = 1;
            tp.Privileges[0].Luid = luid;
            tp.Privileges[0].Attributes = SE_PRIVILEGE_ENABLED;
            AdjustTokenPrivileges(hToken, FALSE, &tp, sizeof(tp), NULL, NULL);
        }
        CloseHandle(hToken);
    }
}

static void ApplyChown(const wchar_t* path, void* ctx) {
    ChownContext* c = (ChownContext*)ctx;

    /* Check if already matching current owner */
    PSECURITY_DESCRIPTOR pSD = NULL;
    PSID pCurrentOwner = NULL;
    if (GetNamedSecurityInfoW((LPWSTR)path, SE_FILE_OBJECT, OWNER_SECURITY_INFORMATION, &pCurrentOwner, NULL, NULL, NULL, &pSD) == ERROR_SUCCESS) {
        if (c->owner_sid && pCurrentOwner && EqualSid(c->owner_sid, pCurrentOwner)) {
            LocalFree(pSD);
            if (c->verbose) {
                wprintf(L"ownership of '%ls' retained as %ls\n", path, c->owner_name);
            }
            return;
        }
        LocalFree(pSD);
    }

    EnablePrivilege(SE_TAKE_OWNERSHIP_NAME);
    EnablePrivilege(SE_RESTORE_NAME);

    SECURITY_INFORMATION sec_info = 0;
    if (c->owner_sid) sec_info |= OWNER_SECURITY_INFORMATION;
    if (c->group_sid) sec_info |= GROUP_SECURITY_INFORMATION;

    DWORD res = SetNamedSecurityInfoW(
        (LPWSTR)path,
        SE_FILE_OBJECT,
        sec_info,
        c->owner_sid,
        c->group_sid,
        NULL,
        NULL
    );

    if (res != ERROR_SUCCESS) {
        if (!c->force) {
            fwprintf(stderr, L"chown: %ls: Failed to change ownership (error %lu)\n", path, res);
        }
    } else if (c->verbose) {
        wprintf(L"changed ownership of '%ls' to %ls\n", path, c->owner_name);
    }
}

bool Builtin_Chown(CommandAST* cmd, int* code) {
    if (cmd->argc < 3 || (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: chown [-R] [-v] [-f] [-h] [owner][:group] file ...\n"
                L"Change file ownership via Windows NT Security Descriptors.\n\n"
                L"  -R          Recursive directory traversal\n"
                L"  -v          Verbose diagnostic output for each file\n"
                L"  -f          Force / suppress error diagnostics\n"
                L"  -h          Operate on symbolic links rather than targets\n");
        *code = (cmd->argc < 3) ? 1 : 0;
        return true;
    }

    ChownContext ctx;
    ctx.recursive = false;
    ctx.verbose = false;
    ctx.force = false;
    ctx.owner_sid = NULL;
    ctx.group_sid = NULL;
    ctx.owner_name[0] = L'\0';
    ctx.group_name[0] = L'\0';

    int arg_idx = 1;
    while (arg_idx < cmd->argc && cmd->argv[arg_idx][0] == L'-' && cmd->argv[arg_idx][1] != L'\0') {
        const wchar_t* arg = cmd->argv[arg_idx];
        if (wcscmp(arg, L"-R") == 0) ctx.recursive = true;
        else if (wcscmp(arg, L"-v") == 0) ctx.verbose = true;
        else if (wcscmp(arg, L"-f") == 0) ctx.force = true;
        else if (wcscmp(arg, L"-h") == 0) { /* symlink no-op */ }
        else break;
        arg_idx++;
    }

    if (arg_idx >= cmd->argc) {
        fwprintf(stderr, L"chown: missing operand\n");
        *code = 1;
        return true;
    }

    const wchar_t* user_spec = cmd->argv[arg_idx++];
    wchar_t user_buf[128];
    wcsncpy(user_buf, user_spec, 127);
    user_buf[127] = L'\0';

    wchar_t* colon = wcschr(user_buf, L':');
    if (!colon) colon = wcschr(user_buf, L'.');

    if (colon) {
        *colon = L'\0';
        wcsncpy_s(ctx.group_name, _countof(ctx.group_name), colon + 1, _TRUNCATE);
    }
    wcsncpy_s(ctx.owner_name, _countof(ctx.owner_name), user_buf, _TRUNCATE);

    BYTE sidBufferOwner[SECURITY_MAX_SID_SIZE];
    BYTE sidBufferGroup[SECURITY_MAX_SID_SIZE];
    DWORD sidSizeOwner = sizeof(sidBufferOwner);
    DWORD sidSizeGroup = sizeof(sidBufferGroup);
    wchar_t domainOwner[256], domainGroup[256];
    DWORD domainSizeOwner = 256, domainSizeGroup = 256;
    SID_NAME_USE sidType;

    if (ctx.owner_name[0] != L'\0') {
        if (LookupAccountNameW(NULL, ctx.owner_name, (PSID)sidBufferOwner, &sidSizeOwner, domainOwner, &domainSizeOwner, &sidType)) {
            ctx.owner_sid = (PSID)sidBufferOwner;
        } else if (!ctx.force) {
            fwprintf(stderr, L"chown: invalid user '%ls'\n", ctx.owner_name);
        }
    }

    if (ctx.group_name[0] != L'\0') {
        if (LookupAccountNameW(NULL, ctx.group_name, (PSID)sidBufferGroup, &sidSizeGroup, domainGroup, &domainSizeGroup, &sidType)) {
            ctx.group_sid = (PSID)sidBufferGroup;
        }
    }

    for (int i = arg_idx; i < cmd->argc; i++) {
        ApplyChown(cmd->argv[i], &ctx);
        if (ctx.recursive) {
            DWORD attr = GetFileAttributesW(cmd->argv[i]);
            if (attr != INVALID_FILE_ATTRIBUTES && (attr & FILE_ATTRIBUTE_DIRECTORY)) {
                RecurseDirectoryTree(cmd->argv[i], ApplyChown, &ctx);
            }
        }
    }

    *code = 0;
    return true;
}

/* ========================================================================= */
/* 5. JOT: BSD Sequence, Random, and Character Generator                     */
/* ========================================================================= */

bool Builtin_Jot(CommandAST* cmd, int* code) {
    if (cmd->argc > 1 && (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: jot [options] [reps [begin [end [s]]]]\n"
                L"Generate sequential, random, or character data (BSD jot).\n\n"
                L"  -r          Generate random data within range\n"
                L"  -b word     Print word repeatedly instead of numbers\n"
                L"  -w format   Custom printf format string (e.g. %%d, 0x%%02x)\n"
                L"  -c          Character mode (abbreviation for -w %%c)\n"
                L"  -s string   Separator string between items (default: newline)\n"
                L"  -n          Do not print trailing separator / newline\n"
                L"  -p prec     Set precision for floating-point output\n");
        *code = 0;
        return true;
    }

    bool random_mode = false;
    const wchar_t* word = NULL;
    const wchar_t* format = NULL;
    bool char_mode = false;
    const wchar_t* sep = L"\n";
    bool no_final_newline = false;
    int precision = -1;

    int arg_idx = 1;
    while (arg_idx < cmd->argc && cmd->argv[arg_idx][0] == L'-' &&
           !iswdigit(cmd->argv[arg_idx][1]) && cmd->argv[arg_idx][1] != L'\0') {
        const wchar_t* opt = cmd->argv[arg_idx];
        if (wcscmp(opt, L"-r") == 0) random_mode = true;
        else if (wcscmp(opt, L"-c") == 0) char_mode = true;
        else if (wcscmp(opt, L"-n") == 0) no_final_newline = true;
        else if (wcscmp(opt, L"-b") == 0 && arg_idx + 1 < cmd->argc) word = cmd->argv[++arg_idx];
        else if (wcscmp(opt, L"-w") == 0 && arg_idx + 1 < cmd->argc) format = cmd->argv[++arg_idx];
        else if (wcscmp(opt, L"-s") == 0 && arg_idx + 1 < cmd->argc) sep = cmd->argv[++arg_idx];
        else if (wcscmp(opt, L"-p") == 0 && arg_idx + 1 < cmd->argc) precision = (int)wcstol(cmd->argv[++arg_idx], NULL, 10);
        else break;
        arg_idx++;
    }

    int pos_args = cmd->argc - arg_idx;
    long reps = (pos_args > 0) ? wcstol(cmd->argv[arg_idx], NULL, 10) : 100;
    double begin = (pos_args > 1) ? wcstod(cmd->argv[arg_idx + 1], NULL) : 1.0;
    double end = (pos_args > 2) ? wcstod(cmd->argv[arg_idx + 2], NULL) : (pos_args > 1 ? begin + reps - 1 : 100.0);
    double step = (pos_args > 3) ? wcstod(cmd->argv[arg_idx + 3], NULL) : 0.0;

    if (pos_args == 1 && reps > 0) {
        begin = 1.0;
        end = (double)reps;
    }

    if (reps == 0) {
        if (step != 0.0) {
            reps = (long)(fabs(end - begin) / fabs(step)) + 1;
        } else {
            reps = 100;
        }
    }

    if (step == 0.0 && reps > 1) {
        step = (end - begin) / (double)(reps - 1);
    }

    if (random_mode) {
        static bool seeded = false;
        if (!seeded) {
            srand((unsigned int)time(NULL) ^ GetCurrentProcessId());
            seeded = true;
        }
    }

    bool is_float = (precision > 0 || (pos_args > 1 && (wcschr(cmd->argv[arg_idx + 1], L'.') != NULL)) ||
                     (pos_args > 2 && (wcschr(cmd->argv[arg_idx + 2], L'.') != NULL)));

    double cur = begin;
    for (long i = 0; i < reps; i++) {
        if (word) {
            wprintf(L"%ls", word);
        } else if (char_mode) {
            wchar_t ch = random_mode ? (wchar_t)((rand() % (int)(end - begin + 1)) + (int)begin) : (wchar_t)(int)cur;
            putwchar(ch);
        } else if (format) {
            if (wcsstr(format, L"%f") || wcsstr(format, L"%g") || wcsstr(format, L"%e")) {
                double val = random_mode ? (begin + ((double)rand() / (double)RAND_MAX) * (end - begin)) : cur;
                wprintf(format, val);
            } else {
                long val = random_mode ? (long)((rand() % (long)(end - begin + 1)) + (long)begin) : (long)cur;
                wprintf(format, val);
            }
        } else if (is_float) {
            double val = random_mode ? (begin + ((double)rand() / (double)RAND_MAX) * (end - begin)) : cur;
            if (precision >= 0) wprintf(L"%.*f", precision, val);
            else wprintf(L"%g", val);
        } else {
            long val = random_mode ? (long)((rand() % (long)(end - begin + 1)) + (long)begin) : (long)cur;
            wprintf(L"%ld", val);
        }

        if (i + 1 < reps) {
            wprintf(L"%ls", sep);
        }
        cur += step;
    }

    if (!no_final_newline) {
        putwchar(L'\n');
    }

    *code = 0;
    return true;
}

/* ========================================================================= */
/* 6. CHFLAGS: BSD File Flags mapped to Windows NT Attributes                */
/* ========================================================================= */

typedef struct {
    bool recursive;
    bool verbose;
    bool force;
    DWORD set_mask;
    DWORD clear_mask;
} ChflagsContext;

static void ApplyChflags(const wchar_t* path, void* ctx) {
    ChflagsContext* c = (ChflagsContext*)ctx;
    DWORD attrs = GetFileAttributesW(path);
    if (attrs == INVALID_FILE_ATTRIBUTES) {
        if (!c->force) fwprintf(stderr, L"chflags: %ls: No such file or directory\n", path);
        return;
    }

    DWORD new_attrs = (attrs | c->set_mask) & ~c->clear_mask;
    if (new_attrs != attrs) {
        if (!SetFileAttributesW(path, new_attrs)) {
            if (!c->force) fwprintf(stderr, L"chflags: %ls: Failed to set attributes\n", path);
            return;
        }
        if (c->verbose) {
            wprintf(L"flags of '%ls' changed\n", path);
        }
    } else if (c->verbose) {
        wprintf(L"flags of '%ls' retained\n", path);
    }
}

bool Builtin_Chflags(CommandAST* cmd, int* code) {
    if (cmd->argc < 3 || (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: chflags [-R] [-v] [-f] [-h] flags file ...\n"
                L"Change file flags mapped to Windows NT file attributes.\n\n"
                L"  -R          Recursive directory processing\n"
                L"  -v          Verbose diagnostic output for each file\n"
                L"  -f          Force / suppress error diagnostics\n"
                L"  -h          Operate on symbolic links themselves\n\n"
                L"Supported Flags:\n"
                L"  hidden / nohidden       Windows FILE_ATTRIBUTE_HIDDEN\n"
                L"  arch / noarch           Windows FILE_ATTRIBUTE_ARCHIVE\n"
                L"  uchg / nouchg / readonly Windows FILE_ATTRIBUTE_READONLY\n"
                L"  system / nosystem       Windows FILE_ATTRIBUTE_SYSTEM\n"
                L"  temp / notemp           Windows FILE_ATTRIBUTE_TEMPORARY\n");
        *code = (cmd->argc < 3) ? 1 : 0;
        return true;
    }

    ChflagsContext ctx;
    ctx.recursive = false;
    ctx.verbose = false;
    ctx.force = false;
    ctx.set_mask = 0;
    ctx.clear_mask = 0;

    int arg_idx = 1;
    while (arg_idx < cmd->argc && cmd->argv[arg_idx][0] == L'-' && cmd->argv[arg_idx][1] != L'\0') {
        const wchar_t* arg = cmd->argv[arg_idx];
        if (wcscmp(arg, L"-R") == 0) ctx.recursive = true;
        else if (wcscmp(arg, L"-v") == 0) ctx.verbose = true;
        else if (wcscmp(arg, L"-f") == 0) ctx.force = true;
        else if (wcscmp(arg, L"-h") == 0) { /* symlink */ }
        else break;
        arg_idx++;
    }

    if (arg_idx >= cmd->argc) {
        fwprintf(stderr, L"chflags: missing flags operand\n");
        *code = 1;
        return true;
    }

    const wchar_t* flags_str = cmd->argv[arg_idx++];
    wchar_t fbuf[256];
    wcsncpy(fbuf, flags_str, 255);
    fbuf[255] = L'\0';

    wchar_t* tok_ctx = NULL;
    wchar_t* token = wcstok(fbuf, L", ", &tok_ctx);
    while (token) {
        if (_wcsicmp(token, L"hidden") == 0) ctx.set_mask |= FILE_ATTRIBUTE_HIDDEN;
        else if (_wcsicmp(token, L"nohidden") == 0) ctx.clear_mask |= FILE_ATTRIBUTE_HIDDEN;
        else if (_wcsicmp(token, L"arch") == 0 || _wcsicmp(token, L"archive") == 0) ctx.set_mask |= FILE_ATTRIBUTE_ARCHIVE;
        else if (_wcsicmp(token, L"noarch") == 0 || _wcsicmp(token, L"noarchive") == 0) ctx.clear_mask |= FILE_ATTRIBUTE_ARCHIVE;
        else if (_wcsicmp(token, L"uchg") == 0 || _wcsicmp(token, L"readonly") == 0 || _wcsicmp(token, L"rdonly") == 0) ctx.set_mask |= FILE_ATTRIBUTE_READONLY;
        else if (_wcsicmp(token, L"nouchg") == 0 || _wcsicmp(token, L"noreadonly") == 0 || _wcsicmp(token, L"nordonly") == 0) ctx.clear_mask |= FILE_ATTRIBUTE_READONLY;
        else if (_wcsicmp(token, L"system") == 0) ctx.set_mask |= FILE_ATTRIBUTE_SYSTEM;
        else if (_wcsicmp(token, L"nosystem") == 0) ctx.clear_mask |= FILE_ATTRIBUTE_SYSTEM;
        else if (_wcsicmp(token, L"temp") == 0 || _wcsicmp(token, L"temporary") == 0) ctx.set_mask |= FILE_ATTRIBUTE_TEMPORARY;
        else if (_wcsicmp(token, L"notemp") == 0 || _wcsicmp(token, L"notemporary") == 0) ctx.clear_mask |= FILE_ATTRIBUTE_TEMPORARY;
        token = wcstok(NULL, L", ", &tok_ctx);
    }

    for (int i = arg_idx; i < cmd->argc; i++) {
        ApplyChflags(cmd->argv[i], &ctx);
        if (ctx.recursive) {
            DWORD attr = GetFileAttributesW(cmd->argv[i]);
            if (attr != INVALID_FILE_ATTRIBUTES && (attr & FILE_ATTRIBUTE_DIRECTORY)) {
                RecurseDirectoryTree(cmd->argv[i], ApplyChflags, &ctx);
            }
        }
    }

    *code = 0;
    return true;
}

/* ========================================================================= */
/* 7. RS: BSD Reshape Data Array / Transpose Utility                         */
/* ========================================================================= */

bool Builtin_Rs(CommandAST* cmd, int* code) {
    if (cmd->argc > 1 && (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: rs [options] [rows [cols]]\n"
                L"Reshape a data array / transpose rows and columns (BSD rs).\n\n"
                L"  -t, -T      Transpose rows and columns\n"
                L"  -c[x]       Input column delimiter character (default: space/tab)\n"
                L"  -C[x]       Output column delimiter character (default: space)\n"
                L"  -w width    Set maximum line width (default: 80)\n"
                L"  -g gutter   Gutter space between output columns (default: 2)\n"
                L"  -j          Right-justify column values\n"
                L"  -z          Squeeze empty delimiter runs\n"
                L"  -e          Consider each input line as a complete row\n");
        *code = 0;
        return true;
    }

    bool transpose = false;
    wchar_t in_delim = L'\0';
    wchar_t out_delim = L' ';
    int width = 80;
    int gutter = 2;
    bool right_justify = false;
    bool line_as_row = false;

    int arg_idx = 1;
    while (arg_idx < cmd->argc && cmd->argv[arg_idx][0] == L'-' &&
           !iswdigit(cmd->argv[arg_idx][1]) && cmd->argv[arg_idx][1] != L'\0') {
        const wchar_t* opt = cmd->argv[arg_idx];
        if (wcscmp(opt, L"-t") == 0 || wcscmp(opt, L"-T") == 0) transpose = true;
        else if (wcscmp(opt, L"-j") == 0) right_justify = true;
        else if (wcscmp(opt, L"-e") == 0) line_as_row = true;
        else if (wcsncmp(opt, L"-c", 2) == 0) in_delim = (opt[2] != L'\0') ? opt[2] : L'\0';
        else if (wcsncmp(opt, L"-C", 2) == 0) out_delim = (opt[2] != L'\0') ? opt[2] : L' ';
        else if (wcscmp(opt, L"-w") == 0 && arg_idx + 1 < cmd->argc) width = (int)wcstol(cmd->argv[++arg_idx], NULL, 10);
        else if (wcsncmp(opt, L"-w", 2) == 0) width = (int)wcstol(opt + 2, NULL, 10);
        else if (wcscmp(opt, L"-g") == 0 && arg_idx + 1 < cmd->argc) gutter = (int)wcstol(cmd->argv[++arg_idx], NULL, 10);
        else if (wcsncmp(opt, L"-g", 2) == 0) gutter = (int)wcstol(opt + 2, NULL, 10);
        else break;
        arg_idx++;
    }

    int req_rows = 0, req_cols = 0;
    if (arg_idx < cmd->argc) req_rows = (int)wcstol(cmd->argv[arg_idx++], NULL, 10);
    if (arg_idx < cmd->argc) req_cols = (int)wcstol(cmd->argv[arg_idx++], NULL, 10);

    /* Read all items from stdin */
    size_t cap = 256, count = 0;
    wchar_t** items = (wchar_t**)malloc(cap * sizeof(wchar_t*));
    if (!items) { *code = 1; return true; }

    wchar_t line[8192];
    while (fgetws(line, sizeof(line) / sizeof(line[0]), stdin)) {
        size_t len = wcslen(line);
        while (len > 0 && (line[len - 1] == L'\r' || line[len - 1] == L'\n')) line[--len] = L'\0';
        if (len == 0 && !line_as_row) continue;

        if (line_as_row) {
            if (count >= cap) {
                size_t new_cap = cap * 2;
                wchar_t** new_items = (wchar_t**)realloc(items, new_cap * sizeof(wchar_t*));
                if (!new_items) break;
                items = new_items;
                cap = new_cap;
            }
            wchar_t* dup = _wcsdup(line);
            if (dup) items[count++] = dup;
        } else if (in_delim != L'\0') {
            wchar_t* p = line;
            while (*p) {
                wchar_t* next = wcschr(p, in_delim);
                if (next) *next = L'\0';
                if (count >= cap) {
                    size_t new_cap = cap * 2;
                    wchar_t** new_items = (wchar_t**)realloc(items, new_cap * sizeof(wchar_t*));
                    if (!new_items) break;
                    items = new_items;
                    cap = new_cap;
                }
                wchar_t* dup = _wcsdup(p);
                if (dup) items[count++] = dup;
                if (!next) break;
                p = next + 1;
            }
        } else {
            wchar_t* p = line;
            while (*p) {
                while (*p && iswspace(*p)) p++;
                if (!*p) break;
                wchar_t* start = p;
                while (*p && !iswspace(*p)) p++;
                size_t wlen = p - start;
                wchar_t* item = (wchar_t*)malloc((wlen + 1) * sizeof(wchar_t));
                if (item) {
                    wcsncpy(item, start, wlen);
                    item[wlen] = L'\0';
                    if (count >= cap) {
                        cap *= 2;
                        wchar_t** new_items = (wchar_t**)realloc(items, cap * sizeof(wchar_t*));
                        if (!new_items) {
                            free(item);
                            break;
                        }
                        items = new_items;
                    }
                    items[count++] = item;
                }
            }
        }
    }

    if (count == 0) {
        free(items);
        *code = 0;
        return true;
    }

    int rows = req_rows;
    int cols = req_cols;
    if (rows == 0 && cols == 0) {
        int max_len = 0;
        for (size_t i = 0; i < count; i++) {
            int l = (int)wcslen(items[i]);
            if (l > max_len) max_len = l;
        }
        int est_cols = (width + gutter) / (max_len + gutter > 0 ? max_len + gutter : 1);
        if (est_cols < 1) est_cols = 1;
        cols = est_cols;
        rows = (int)((count + cols - 1) / cols);
    } else if (rows > 0 && cols == 0) {
        cols = (int)((count + rows - 1) / rows);
    } else if (cols > 0 && rows == 0) {
        rows = (int)((count + cols - 1) / cols);
    }

    if (cols < 1) cols = 1;
    if (rows < 1) rows = 1;

    if (transpose) {
        int tmp = rows;
        rows = cols;
        cols = tmp;
    }

    /* Compute column widths */
    int* col_widths = (int*)calloc(cols, sizeof(int));
    if (!col_widths) {
        for (size_t i = 0; i < count; i++) free(items[i]);
        free(items);
        *code = 1;
        return true;
    }
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            size_t idx = transpose ? (size_t)(c * rows + r) : (size_t)(r * cols + c);
            if (idx < count) {
                int item_len = (int)wcslen(items[idx]);
                if (item_len > col_widths[c]) col_widths[c] = item_len;
            }
        }
    }

    /* Print matrix */
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            size_t idx = transpose ? (size_t)(c * rows + r) : (size_t)(r * cols + c);
            const wchar_t* str = (idx < count) ? items[idx] : L"";
            int pad = col_widths[c] - (int)wcslen(str);

            if (c > 0) {
                for (int g = 0; g < gutter; g++) putwchar(out_delim);
            }

            if (right_justify) {
                for (int k = 0; k < pad; k++) putwchar(L' ');
                wprintf(L"%ls", str);
            } else {
                wprintf(L"%ls", str);
                if (c + 1 < cols) {
                    for (int k = 0; k < pad; k++) putwchar(L' ');
                }
            }
        }
        putwchar(L'\n');
    }

    for (size_t i = 0; i < count; i++) free(items[i]);
    free(items);
    free(col_widths);

    *code = 0;
    return true;
}

/* ========================================================================= */
/* 8. LOCKF: BSD Command Execution with Advisory/Exclusive File Locking      */
/* ========================================================================= */

bool Builtin_Lockf(IShell* shell, CommandAST* cmd, int* code) {
    (void)shell;
    if (cmd->argc < 3 || (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: lockf [-kns] [-t seconds] file command [args...]\n"
                L"Execute a command while holding an exclusive/shared lock on a file (BSD lockf).\n\n"
                L"  -k          Keep lock open across command termination\n"
                L"  -s          Acquire shared lock (default: exclusive)\n"
                L"  -n          Non-blocking: fail immediately if locked\n"
                L"  -t seconds  Timeout in seconds waiting to acquire lock\n");
        *code = (cmd->argc < 3) ? 1 : 0;
        return true;
    }

    bool keep_lock = false;
    bool shared = false;
    bool nonblocking = false;
    int timeout_sec = -1;

    int arg_idx = 1;
    while (arg_idx < cmd->argc && cmd->argv[arg_idx][0] == L'-' && cmd->argv[arg_idx][1] != L'\0') {
        const wchar_t* opt = cmd->argv[arg_idx];
        if (wcscmp(opt, L"-k") == 0) keep_lock = true;
        else if (wcscmp(opt, L"-s") == 0) shared = true;
        else if (wcscmp(opt, L"-n") == 0) nonblocking = true;
        else if (wcscmp(opt, L"-t") == 0 && arg_idx + 1 < cmd->argc) {
            timeout_sec = (int)wcstol(cmd->argv[++arg_idx], NULL, 10);
        } else if (wcsncmp(opt, L"-t", 2) == 0) {
            timeout_sec = (int)wcstol(opt + 2, NULL, 10);
        } else {
            break;
        }
        arg_idx++;
    }

    if (arg_idx + 1 >= cmd->argc) {
        fwprintf(stderr, L"lockf: missing file or command\n");
        *code = 1;
        return true;
    }

    const wchar_t* lock_file = cmd->argv[arg_idx++];
    HANDLE hFile = CreateFileW(
        lock_file,
        GENERIC_READ | (shared ? 0 : GENERIC_WRITE),
        FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
        NULL,
        OPEN_ALWAYS,
        FILE_ATTRIBUTE_NORMAL,
        NULL
    );

    if (hFile == INVALID_HANDLE_VALUE) {
        hFile = CreateFileW(
            lock_file,
            GENERIC_READ,
            FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
            NULL,
            OPEN_ALWAYS,
            FILE_ATTRIBUTE_NORMAL,
            NULL
        );
    }

    if (hFile == INVALID_HANDLE_VALUE) {
        fwprintf(stderr, L"lockf: %ls: Cannot open lock file\n", lock_file);
        *code = 1;
        return true;
    }

    DWORD lock_flags = (shared ? 0 : LOCKFILE_EXCLUSIVE_LOCK) | (nonblocking ? LOCKFILE_FAIL_IMMEDIATELY : 0);
    OVERLAPPED ov;
    memset(&ov, 0, sizeof(ov));

    bool locked = false;
    DWORD start_time = GetTickCount();
    while (true) {
        if (LockFileEx(hFile, lock_flags | LOCKFILE_FAIL_IMMEDIATELY, 0, MAXDWORD, MAXDWORD, &ov)) {
            locked = true;
            break;
        }

        if (nonblocking) break;

        if (timeout_sec >= 0) {
            DWORD elapsed = (GetTickCount() - start_time) / 1000;
            if ((int)elapsed >= timeout_sec) break;
        }

        Sleep(50);
    }

    if (!locked) {
        fwprintf(stderr, L"lockf: %ls: already locked\n", lock_file);
        CloseHandle(hFile);
        *code = 1;
        return true;
    }

    int child_exit = 0;
    if (shell) {
        wchar_t full_cmd[4096] = {0};
        for (int i = arg_idx; i < cmd->argc; i++) {
            if (!Ksh_AppendShellWord(full_cmd, sizeof(full_cmd) / sizeof(full_cmd[0]), cmd->argv[i])) {
                fwprintf(stderr, L"lockf: command too long\n");
                child_exit = 1;
                break;
            }
        }
        if (child_exit == 0) {
            child_exit = shell->ExecuteLine(shell, full_cmd);
        }
    } else {
        /* Fallback to CreateProcess with proper Win32 escaping */
        wchar_t* cmdline = BuildWin32CommandLine(cmd->argv + arg_idx, cmd->argc - arg_idx);
        if (!cmdline) {
            if (!keep_lock) {
                UnlockFileEx(hFile, 0, MAXDWORD, MAXDWORD, &ov);
                CloseHandle(hFile);
            }
            *code = 1;
            return true;
        }

        STARTUPINFOW si;
        PROCESS_INFORMATION pi;
        memset(&si, 0, sizeof(si));
        si.cb = sizeof(si);
        memset(&pi, 0, sizeof(pi));

        DWORD proc_exit = 1;
        if (CreateProcessW(NULL, cmdline, NULL, NULL, TRUE, 0, NULL, NULL, &si, &pi)) {
            WaitForSingleObject(pi.hProcess, INFINITE);
            GetExitCodeProcess(pi.hProcess, &proc_exit);
            CloseHandle(pi.hThread);
            CloseHandle(pi.hProcess);
            child_exit = (int)proc_exit;
        } else {
            fwprintf(stderr, L"lockf: %ls: execution failed\n", cmd->argv[arg_idx]);
            child_exit = 1;
        }
        free(cmdline);
    }

    if (!keep_lock) {
        UnlockFileEx(hFile, 0, MAXDWORD, MAXDWORD, &ov);
        CloseHandle(hFile);
    }

    *code = (int)child_exit;
    return true;
}

/* ========================================================================= */
/* Source Module: src/builtins/builtins_bsd2.c                                */
/* ========================================================================= */

#include <direct.h>
#include <sys/stat.h>
#include <time.h>

/* ========================================================================= */
/*                          BSD Scripting & Core Utilities                   */
/*             unlink, link, tsort, nice, nohup, patch, pax                  */
/* ========================================================================= */

/* ========================================================================= */
/* 1. UNLINK: POSIX / BSD System Call Primitive                              */
/* ========================================================================= */

bool Builtin_Unlink(CommandAST* cmd, int* code) {
    if (cmd->argc == 2 && (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: unlink file\n"
                L"Call the unlink function to remove the specified file.\n");
        *code = 0;
        return true;
    }

    if (cmd->argc < 2) {
        fwprintf(stderr, L"unlink: missing operand\n");
        *code = 1;
        return true;
    }
    if (cmd->argc > 2) {
        fwprintf(stderr, L"unlink: extra operand '%ls'\n", cmd->argv[2]);
        *code = 1;
        return true;
    }

    const wchar_t* path = cmd->argv[1];
    DWORD attrs = GetFileAttributesW(path);
    if (attrs == INVALID_FILE_ATTRIBUTES) {
        fwprintf(stderr, L"unlink: %ls: No such file or directory\n", path);
        *code = 1;
        return true;
    }

    if (attrs & FILE_ATTRIBUTE_DIRECTORY) {
        fwprintf(stderr, L"unlink: %ls: Is a directory\n", path);
        *code = 1;
        return true;
    }

    if (!DeleteFileW(path)) {
        /* Clear read-only if needed and retry */
        if (attrs & FILE_ATTRIBUTE_READONLY) {
            SetFileAttributesW(path, attrs & ~FILE_ATTRIBUTE_READONLY);
            if (DeleteFileW(path)) {
                *code = 0;
                return true;
            }
        }
        fwprintf(stderr, L"unlink: %ls: Cannot delete file (error %lu)\n", path, GetLastError());
        *code = 1;
        return true;
    }

    *code = 0;
    return true;
}

/* ========================================================================= */
/* 2. LINK: POSIX / BSD Hard Link Primitive                                  */
/* ========================================================================= */

bool Builtin_Link(CommandAST* cmd, int* code) {
    if (cmd->argc == 2 && (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: link file1 file2\n"
                L"Create a hard link file2 pointing to file1.\n");
        *code = 0;
        return true;
    }

    if (cmd->argc < 3) {
        fwprintf(stderr, L"link: missing operand\n");
        *code = 1;
        return true;
    }
    if (cmd->argc > 3) {
        fwprintf(stderr, L"link: extra operand '%ls'\n", cmd->argv[3]);
        *code = 1;
        return true;
    }

    const wchar_t* target = cmd->argv[1];
    const wchar_t* link_name = cmd->argv[2];

    if (!CreateHardLinkW(link_name, target, NULL)) {
        /* On filesystems where hard links are unsupported (such as ReFS or FAT),
           fallback gracefully to unprivileged symbolic link */
        DWORD flags = 0x2; /* SYMBOLIC_LINK_FLAG_ALLOW_UNPRIVILEGED_CREATE */
        if (!CreateSymbolicLinkW(link_name, target, flags)) {
            if (!CreateSymbolicLinkW(link_name, target, 0)) {
                fwprintf(stderr, L"link: %ls: %ls: Cannot create link (error %lu)\n",
                         target, link_name, GetLastError());
                *code = 1;
                return true;
            }
        }
    }

    *code = 0;
    return true;
}

/* ========================================================================= */
/* 3. TSORT: Topological Sort (POSIX / BSD)                                  */
/* ========================================================================= */

typedef struct {
    wchar_t name[256];
    int in_degree;
    int* successors;
    int succ_count;
    int succ_cap;
} TsortNode;

typedef struct {
    TsortNode* nodes;
    int count;
    int cap;
} TsortGraph;

static int TsortFindOrAdd(TsortGraph* g, const wchar_t* name) {
    for (int i = 0; i < g->count; i++) {
        if (wcscmp(g->nodes[i].name, name) == 0) return i;
    }
    if (g->count >= g->cap) {
        g->cap = (g->cap == 0) ? 64 : g->cap * 2;
        TsortNode* new_nodes = (TsortNode*)realloc(g->nodes, g->cap * sizeof(TsortNode));
        if (!new_nodes) return -1;
        g->nodes = new_nodes;
    }
    int idx = g->count++;
    wcsncpy_s(g->nodes[idx].name, _countof(g->nodes[idx].name), name, _TRUNCATE);
    g->nodes[idx].in_degree = 0;
    g->nodes[idx].successors = NULL;
    g->nodes[idx].succ_count = 0;
    g->nodes[idx].succ_cap = 0;
    return idx;
}

static void TsortAddEdge(TsortGraph* g, int from, int to) {
    if (from < 0 || to < 0 || from == to) return;
    TsortNode* fn = &g->nodes[from];
    for (int i = 0; i < fn->succ_count; i++) {
        if (fn->successors[i] == to) return;
    }
    if (fn->succ_count >= fn->succ_cap) {
        fn->succ_cap = (fn->succ_cap == 0) ? 8 : fn->succ_cap * 2;
        int* new_succ = (int*)realloc(fn->successors, fn->succ_cap * sizeof(int));
        if (!new_succ) return;
        fn->successors = new_succ;
    }
    fn->successors[fn->succ_count++] = to;
    g->nodes[to].in_degree++;
}

bool Builtin_Tsort(CommandAST* cmd, int* code) {
    if (cmd->argc > 1 && (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: tsort [-q] [file]\n"
                L"Perform topological sort on ordered pairs of nodes (POSIX/BSD).\n\n"
                L"  -q          Quiet: suppress cycle warnings\n");
        *code = 0;
        return true;
    }

    bool quiet = false;
    const wchar_t* filename = NULL;

    for (int i = 1; i < cmd->argc; i++) {
        if (wcscmp(cmd->argv[i], L"-q") == 0) {
            quiet = true;
        } else if (!filename) {
            filename = cmd->argv[i];
        }
    }

    FILE* fp = stdin;
    if (filename && wcscmp(filename, L"-") != 0) {
        fp = _wfsopen(filename, L"r", _SH_DENYNO);
        if (!fp) {
            fwprintf(stderr, L"tsort: %ls: Cannot open file\n", filename);
            *code = 1;
            return true;
        }
    }

    TsortGraph g;
    memset(&g, 0, sizeof(g));

    wchar_t token[256];
    wchar_t prev_token[256];
    bool have_prev = false;

    while (fgetws(token, sizeof(token) / sizeof(token[0]), fp)) {
        wchar_t* p = token;
        while (*p) {
            while (*p && iswspace(*p)) p++;
            if (!*p) break;
            wchar_t* start = p;
            while (*p && !iswspace(*p)) p++;
            wchar_t saved = *p;
            *p = L'\0';

            if (!have_prev) {
                wcsncpy(prev_token, start, 255);
                prev_token[255] = L'\0';
                have_prev = true;
            } else {
                int u = TsortFindOrAdd(&g, prev_token);
                int v = TsortFindOrAdd(&g, start);
                TsortAddEdge(&g, u, v);
                have_prev = false;
            }

            if (saved == L'\0') break;
            *p = saved;
        }
    }

    if (fp != stdin) fclose(fp);

    if (have_prev) {
        fwprintf(stderr, L"tsort: odd number of tokens\n");
        for (int i = 0; i < g.count; i++) free(g.nodes[i].successors);
        free(g.nodes);
        *code = 1;
        return true;
    }

    if (g.count == 0) {
        *code = 0;
        return true;
    }

    /* Kahn's algorithm */
    int* queue = (int*)malloc(g.count * sizeof(int));
    int q_head = 0, q_tail = 0;

    for (int i = 0; i < g.count; i++) {
        if (g.nodes[i].in_degree == 0) {
            queue[q_tail++] = i;
        }
    }

    int emitted = 0;
    while (q_head < q_tail) {
        int u = queue[q_head++];
        wprintf(L"%ls\n", g.nodes[u].name);
        emitted++;

        for (int i = 0; i < g.nodes[u].succ_count; i++) {
            int v = g.nodes[u].successors[i];
            if (--g.nodes[v].in_degree == 0) {
                queue[q_tail++] = v;
            }
        }
    }

    bool has_cycle = (emitted < g.count);
    if (has_cycle) {
        if (!quiet) {
            fwprintf(stderr, L"tsort: cycle in data\n");
        }
        /* Emit remaining nodes in cycle */
        for (int i = 0; i < g.count; i++) {
            if (g.nodes[i].in_degree > 0) {
                wprintf(L"%ls\n", g.nodes[i].name);
            }
        }
    }

    for (int i = 0; i < g.count; i++) free(g.nodes[i].successors);
    free(g.nodes);
    free(queue);

    *code = has_cycle ? 1 : 0;
    return true;
}

/* ========================================================================= */
/* 4. NICE: Process Priority Scheduling (POSIX / BSD)                        */
/* ========================================================================= */

bool Builtin_Nice(IShell* shell, CommandAST* cmd, int* code) {
    if (cmd->argc > 1 && (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: nice [-n increment] utility [argument ...]\n"
                L"Execute utility with an altered process scheduling priority.\n\n"
                L"  -n increment  Priority adjustment (-20 to +19, default: 10)\n");
        *code = 0;
        return true;
    }

    if (cmd->argc == 1) {
        /* Print current nice value: 0 for normal */
        DWORD prio = GetPriorityClass(GetCurrentProcess());
        int nice_val = 0;
        if (prio == IDLE_PRIORITY_CLASS) nice_val = 19;
        else if (prio == BELOW_NORMAL_PRIORITY_CLASS) nice_val = 10;
        else if (prio == ABOVE_NORMAL_PRIORITY_CLASS) nice_val = -5;
        else if (prio == HIGH_PRIORITY_CLASS) nice_val = -10;
        else if (prio == REALTIME_PRIORITY_CLASS) nice_val = -20;
        wprintf(L"%d\n", nice_val);
        *code = 0;
        return true;
    }

    int inc = 10;
    int arg_idx = 1;

    while (arg_idx < cmd->argc && cmd->argv[arg_idx][0] == L'-' && cmd->argv[arg_idx][1] != L'\0') {
        const wchar_t* opt = cmd->argv[arg_idx];
        if (wcscmp(opt, L"-n") == 0 && arg_idx + 1 < cmd->argc) {
            inc = (int)wcstol(cmd->argv[++arg_idx], NULL, 10);
        } else if (wcsncmp(opt, L"-n", 2) == 0 && iswdigit(opt[2])) {
            inc = (int)wcstol(opt + 2, NULL, 10);
        } else if (iswdigit(opt[1])) {
            inc = (int)wcstol(opt + 1, NULL, 10);
        } else {
            break;
        }
        arg_idx++;
    }

    if (arg_idx >= cmd->argc) {
        fwprintf(stderr, L"nice: missing utility\n");
        *code = 1;
        return true;
    }

    DWORD prio_class = NORMAL_PRIORITY_CLASS;
    if (inc >= 10) prio_class = IDLE_PRIORITY_CLASS;
    else if (inc > 0) prio_class = BELOW_NORMAL_PRIORITY_CLASS;
    else if (inc <= -10) prio_class = HIGH_PRIORITY_CLASS;
    else if (inc < 0) prio_class = ABOVE_NORMAL_PRIORITY_CLASS;

    DWORD old_prio = GetPriorityClass(GetCurrentProcess());
    SetPriorityClass(GetCurrentProcess(), prio_class);

    int exit_code = 0;
    if (shell) {
        wchar_t full_cmd[4096] = {0};
        for (int i = arg_idx; i < cmd->argc; i++) {
            if (!Ksh_AppendShellWord(full_cmd, sizeof(full_cmd) / sizeof(full_cmd[0]), cmd->argv[i])) {
                fwprintf(stderr, L"nice: command too long\n");
                exit_code = 126;
                break;
            }
        }
        if (exit_code == 0) {
            exit_code = shell->ExecuteLine(shell, full_cmd);
        }
    }

    SetPriorityClass(GetCurrentProcess(), old_prio);
    *code = exit_code;
    return true;
}

/* ========================================================================= */
/* 5. NOHUP: Terminal Hangup Immunity (POSIX / BSD)                          */
/* ========================================================================= */

bool Builtin_Nohup(IShell* shell, CommandAST* cmd, int* code) {
    if (cmd->argc > 1 && (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: nohup utility [argument ...]\n"
                L"Invoke a utility immune to hangups, with output to nohup.out.\n");
        *code = 0;
        return true;
    }

    if (cmd->argc < 2) {
        fwprintf(stderr, L"nohup: missing utility\n");
        *code = 127;
        return true;
    }

    /* Check if stdout is interactive terminal */
    bool stdout_is_tty = (_isatty(_fileno(stdout)) != 0);
    FILE* nohup_file = NULL;

    if (stdout_is_tty) {
        nohup_file = _wfsopen(L"nohup.out", L"a+", _SH_DENYNO);
        if (!nohup_file) {
            const wchar_t* home = _wgetenv(L"USERPROFILE");
            if (home) {
                wchar_t home_path[MAX_PATH];
                swprintf(home_path, sizeof(home_path) / sizeof(home_path[0]), L"%ls\\nohup.out", home);
                nohup_file = _wfsopen(home_path, L"a+", _SH_DENYNO);
                if (nohup_file) {
                    fwprintf(stderr, L"nohup: appending output to %ls\n", home_path);
                }
            }
        } else {
            fwprintf(stderr, L"nohup: appending output to nohup.out\n");
        }
    }

    /* Temporarily ignore ctrl handler */
    SetConsoleCtrlHandler(NULL, TRUE);

    int exit_code = 0;
    if (shell) {
        wchar_t full_cmd[4096] = {0};
        for (int i = 1; i < cmd->argc; i++) {
            if (!Ksh_AppendShellWord(full_cmd, sizeof(full_cmd) / sizeof(full_cmd[0]), cmd->argv[i])) {
                fwprintf(stderr, L"nohup: command line too long\n");
                exit_code = 126;
                break;
            }
        }

        if (exit_code == 0) {
            int old_stdout_fd = -1;
            if (nohup_file) {
                fflush(stdout);
                old_stdout_fd = _dup(_fileno(stdout));
                _dup2(_fileno(nohup_file), _fileno(stdout));
            }

            exit_code = shell->ExecuteLine(shell, full_cmd);

            if (nohup_file) {
                fflush(stdout);
                if (old_stdout_fd >= 0) {
                    _dup2(old_stdout_fd, _fileno(stdout));
                    _close(old_stdout_fd);
                }
                fclose(nohup_file);
            }
        }
    }

    SetConsoleCtrlHandler(NULL, FALSE);
    *code = exit_code;
    return true;
}

/* ========================================================================= */
/* 6. PATCH: Unified Diff Applicator (BSD patch)                             */
/* ========================================================================= */

static const wchar_t* StripPath(const wchar_t* path, int p_strip) {
    if (p_strip <= 0) return path;
    const wchar_t* p = path;
    for (int i = 0; i < p_strip && *p; i++) {
        while (*p && *p != L'/' && *p != L'\\') p++;
        if (*p) p++;
    }
    return (*p) ? p : path;
}

static bool PatchAppend(wchar_t*** arr, size_t* count, size_t* cap, wchar_t* line) {
    if (!*arr || !line) { free(line); return false; }
    if (*count >= *cap) {
        size_t ncap = *cap * 2;
        wchar_t** narr = (wchar_t**)realloc(*arr, ncap * sizeof(wchar_t*));
        if (!narr) { free(line); return false; }
        *arr = narr;
        *cap = ncap;
    }
    (*arr)[(*count)++] = line;
    return true;
}

bool Builtin_Patch(CommandAST* cmd, int* code) {
    if (cmd->argc > 1 && (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: patch [-R] [-s] [-b] [-p strip] [-i patchfile] [-o outfile] [-d dir] [origfile]\n"
                L"Apply unified diff patches to files (BSD patch).\n\n"
                L"  -p[num]     Strip num leading path components\n"
                L"  -i file     Read patch from file instead of stdin\n"
                L"  -o file     Output patched file to file\n"
                L"  -R          Reverse the patch\n"
                L"  -s, -q      Silent / quiet mode\n"
                L"  -b          Create backup of original file (.orig)\n"
                L"  -d dir      Change working directory before patching\n");
        *code = 0;
        return true;
    }

    int p_strip = 0;
    const wchar_t* patch_file = NULL;
    const wchar_t* out_file = NULL;
    const wchar_t* orig_file = NULL;
    const wchar_t* work_dir = NULL;
    bool reverse = false;
    bool quiet = false;
    bool backup = false;

    for (int i = 1; i < cmd->argc; i++) {
        const wchar_t* arg = cmd->argv[i];
        if (wcscmp(arg, L"-R") == 0) reverse = true;
        else if (wcscmp(arg, L"-s") == 0 || wcscmp(arg, L"-q") == 0) quiet = true;
        else if (wcscmp(arg, L"-b") == 0) backup = true;
        else if (wcscmp(arg, L"-i") == 0 && i + 1 < cmd->argc) patch_file = cmd->argv[++i];
        else if (wcscmp(arg, L"-o") == 0 && i + 1 < cmd->argc) out_file = cmd->argv[++i];
        else if (wcscmp(arg, L"-d") == 0 && i + 1 < cmd->argc) work_dir = cmd->argv[++i];
        else if (wcscmp(arg, L"-p") == 0 && i + 1 < cmd->argc) p_strip = (int)wcstol(cmd->argv[++i], NULL, 10);
        else if (wcsncmp(arg, L"-p", 2) == 0 && iswdigit(arg[2])) p_strip = (int)wcstol(arg + 2, NULL, 10);
        else if (arg[0] != L'-' && !orig_file) orig_file = arg;
    }

    if (work_dir) {
        _wchdir(work_dir);
    }

    FILE* pfp = stdin;
    if (patch_file) {
        pfp = _wfsopen(patch_file, L"r", _SH_DENYNO);
        if (!pfp) {
            fwprintf(stderr, L"patch: %ls: Cannot open patch file\n", patch_file);
            *code = 1;
            return true;
        }
    }

    /* Read all patch lines */
    size_t pcap = 512, pcount = 0;
    wchar_t** plines = (wchar_t**)malloc(pcap * sizeof(wchar_t*));
    if (!plines) {
        if (pfp != stdin) fclose(pfp);
        *code = 1;
        return true;
    }
    wchar_t lbuf[8192];
    while (fgetws(lbuf, sizeof(lbuf) / sizeof(lbuf[0]), pfp)) {
        PatchAppend(&plines, &pcount, &pcap, _wcsdup(lbuf));
    }
    if (pfp != stdin) fclose(pfp);

    /* Find target filename if not specified */
    wchar_t detected_file[MAX_PATH] = {0};
    for (size_t i = 0; i < pcount && !orig_file; i++) {
        if (wcsncmp(plines[i], L"+++ ", 4) == 0) {
            wchar_t* tab = wcschr(plines[i] + 4, L'\t');
            if (tab) *tab = L'\0';
            wchar_t* nl = wcschr(plines[i] + 4, L'\n');
            if (nl) *nl = L'\0';
            orig_file = StripPath(plines[i] + 4, p_strip);
            wcsncpy_s(detected_file, _countof(detected_file), orig_file, _TRUNCATE);
            orig_file = detected_file;
            break;
        }
    }

    if (!orig_file) {
        fwprintf(stderr, L"patch: cannot determine target file\n");
        for (size_t i = 0; i < pcount; i++) free(plines[i]);
        free(plines);
        *code = 1;
        return true;
    }

    /* Read target file lines */
    FILE* tfp = _wfsopen(orig_file, L"r", _SH_DENYNO);
    if (!tfp) {
        fwprintf(stderr, L"patch: %ls: No such file or directory\n", orig_file);
        for (size_t i = 0; i < pcount; i++) free(plines[i]);
        free(plines);
        *code = 1;
        return true;
    }

    size_t fcap = 512, fcount = 0;
    wchar_t** flines = (wchar_t**)malloc(fcap * sizeof(wchar_t*));
    if (!flines) {
        fclose(tfp);
        for (size_t i = 0; i < pcount; i++) free(plines[i]);
        free(plines);
        *code = 1;
        return true;
    }
    while (fgetws(lbuf, sizeof(lbuf) / sizeof(lbuf[0]), tfp)) {
        PatchAppend(&flines, &fcount, &fcap, _wcsdup(lbuf));
    }
    fclose(tfp);

    if (!quiet) {
        wprintf(L"patching file %ls\n", orig_file);
    }

    /* Result lines buffer */
    size_t rcap = fcount + 512, rcount = 0;
    wchar_t** rlines = (wchar_t**)malloc(rcap * sizeof(wchar_t*));
    if (!rlines) {
        for (size_t i = 0; i < pcount; i++) free(plines[i]);
        free(plines);
        for (size_t i = 0; i < fcount; i++) free(flines[i]);
        free(flines);
        *code = 1;
        return true;
    }
    size_t cur_src = 0;

    for (size_t i = 0; i < pcount; i++) {
        if (wcsncmp(plines[i], L"@@ -", 4) == 0) {
            int o_start = 1, o_count = 1, n_start = 1, n_count = 1;
            swscanf(plines[i], L"@@ -%d,%d +%d,%d @@", &o_start, &o_count, &n_start, &n_count);
            if (o_count == 1 && wcschr(plines[i], L',') == NULL) {
                swscanf(plines[i], L"@@ -%d +%d @@", &o_start, &n_start);
            }

            int target_line = (reverse ? n_start : o_start) - 1;
            if (target_line < 0) target_line = 0;

            /* Copy unchanged source lines up to target_line */
            while (cur_src < (size_t)target_line && cur_src < fcount) {
                PatchAppend(&rlines, &rcount, &rcap, _wcsdup(flines[cur_src++]));
            }

            /* Process hunk lines */
            i++;
            while (i < pcount && (plines[i][0] == L' ' || plines[i][0] == L'+' || plines[i][0] == L'-')) {
                wchar_t type = plines[i][0];
                if (reverse) {
                    if (type == L'+') type = L'-';
                    else if (type == L'-') type = L'+';
                }

                if (type == L' ') {
                    if (cur_src < fcount) {
                        PatchAppend(&rlines, &rcount, &rcap, _wcsdup(flines[cur_src++]));
                    }
                } else if (type == L'-') {
                    if (cur_src < fcount) cur_src++;
                } else if (type == L'+') {
                    PatchAppend(&rlines, &rcount, &rcap, _wcsdup(plines[i] + 1));
                }
                i++;
            }
            i--; /* step back for outer loop */
        }
    }

    /* Copy any remaining trailing lines */
    while (cur_src < fcount) {
        PatchAppend(&rlines, &rcount, &rcap, _wcsdup(flines[cur_src++]));
    }

    /* Optional backup */
    if (backup) {
        wchar_t bpath[MAX_PATH];
        swprintf(bpath, sizeof(bpath) / sizeof(bpath[0]), L"%ls.orig", orig_file);
        CopyFileW(orig_file, bpath, FALSE);
    }

    /* Write target file */
    const wchar_t* dest_file = out_file ? out_file : orig_file;
    FILE* wfp = _wfsopen(dest_file, L"w", _SH_DENYWR);
    if (!wfp) {
        fwprintf(stderr, L"patch: %ls: Cannot write file\n", dest_file);
        *code = 1;
    } else {
        for (size_t j = 0; j < rcount; j++) {
            fputws(rlines[j], wfp);
        }
        fclose(wfp);
        *code = 0;
    }

    for (size_t j = 0; j < pcount; j++) free(plines[j]);
    free(plines);
    for (size_t j = 0; j < fcount; j++) free(flines[j]);
    free(flines);
    for (size_t j = 0; j < rcount; j++) free(rlines[j]);
    free(rlines);

    return true;
}

/* ========================================================================= */
/* 7. PAX: Portable Archive Interchange (POSIX / BSD)                        */
/* ========================================================================= */

#pragma pack(push, 1)
typedef struct {
    char name[100];
    char mode[8];
    char uid[8];
    char gid[8];
    char size[12];
    char mtime[12];
    char chksum[8];
    char typeflag;
    char linkname[100];
    char magic[6];
    char version[2];
    char uname[32];
    char gname[32];
    char devmajor[8];
    char devminor[8];
    char prefix[155];
    char pad[12];
} TarHeader;
#pragma pack(pop)

static unsigned int TarChecksum(const TarHeader* h) {
    const unsigned char* p = (const unsigned char*)h;
    unsigned int sum = 0;
    for (size_t i = 0; i < sizeof(TarHeader); i++) {
        if (i >= offsetof(TarHeader, chksum) && i < offsetof(TarHeader, chksum) + sizeof(h->chksum)) {
            sum += ' ';
        } else {
            sum += p[i];
        }
    }
    return sum;
}

static void FormatOctal(char* dst, size_t size, unsigned __int64 val) {
    snprintf(dst, size, "%0*llo", (int)(size - 1), val);
}

static bool MatchPattern(const wchar_t* pat, const wchar_t* str) {
    if (!pat || !*pat || wcscmp(pat, L"*") == 0) return true;
    return wcsstr(str, pat) != NULL;
}

static bool TarIsPathSafe(const wchar_t* path) {
    if (!path || !*path) return false;
    if (!path || !*path) return false;
    /* Reject absolute paths: leading slash or backslash */
    if (path[0] == L'/' || path[0] == L'\\') return false;
    /* Reject drive letters or NTFS alternate data streams */
    if (wcschr(path, L':') != NULL) return false;
    /* Reject directory traversal with .. */
    const wchar_t* p = path;
    while (*p) {
        if (p[0] == L'.' && p[1] == L'.') {
            if (p == path || p[-1] == L'/' || p[-1] == L'\\') {
                if (p[2] == L'\0' || p[2] == L'/' || p[2] == L'\\') {
                    return false;
                }
            }
        }
        p++;
    }
    return true;
}

static void TarEnsureParentDirs(const wchar_t* path) {
    wchar_t buf[MAX_PATH];
    wcsncpy_s(buf, _countof(buf), path, _TRUNCATE);
    wchar_t* p = buf;
    while (*p) {
        if (*p == L'/' || *p == L'\\') {
            *p = L'\0';
            if (buf[0] != L'\0' && wcscmp(buf, L".") != 0 && wcscmp(buf, L"..") != 0 && !(buf[1] == L':' && buf[2] == L'\0')) {
                CreateDirectoryW(buf, NULL);
            }
            *p = L'\\';
        }
        p++;
    }
}

static void PaxCopyTree(const wchar_t* src, const wchar_t* dst, bool verbose, bool newer_only) {
    DWORD attr = GetFileAttributesW(src);
    if (attr == INVALID_FILE_ATTRIBUTES) return;

    if (attr & FILE_ATTRIBUTE_DIRECTORY) {
        CreateDirectoryW(dst, NULL);
        wchar_t search[MAX_PATH * 2];
        swprintf(search, sizeof(search) / sizeof(search[0]), L"%ls\\*", src);
        WIN32_FIND_DATAW fd;
        HANDLE hFind = FindFirstFileW(search, &fd);
        if (hFind != INVALID_HANDLE_VALUE) {
            do {
                if (wcscmp(fd.cFileName, L".") == 0 || wcscmp(fd.cFileName, L"..") == 0) continue;
                wchar_t ssub[MAX_PATH * 2], dsub[MAX_PATH * 2];
                swprintf(ssub, sizeof(ssub) / sizeof(ssub[0]), L"%ls\\%ls", src, fd.cFileName);
                swprintf(dsub, sizeof(dsub) / sizeof(dsub[0]), L"%ls\\%ls", dst, fd.cFileName);
                PaxCopyTree(ssub, dsub, verbose, newer_only);
            } while (FindNextFileW(hFind, &fd));
            FindClose(hFind);
        }
    } else {
        if (newer_only) {
            WIN32_FIND_DATAW fd_src, fd_dst;
            HANDLE hs = FindFirstFileW(src, &fd_src);
            HANDLE hd = FindFirstFileW(dst, &fd_dst);
            if (hs != INVALID_HANDLE_VALUE && hd != INVALID_HANDLE_VALUE) {
                if (CompareFileTime(&fd_src.ftLastWriteTime, &fd_dst.ftLastWriteTime) <= 0) {
                    FindClose(hs); FindClose(hd);
                    return;
                }
            }
            if (hs != INVALID_HANDLE_VALUE) FindClose(hs);
            if (hd != INVALID_HANDLE_VALUE) FindClose(hd);
        }
        CopyFileW(src, dst, FALSE);
        if (verbose) {
            wprintf(L"%ls\n", src);
        }
    }
}

bool Builtin_Pax(IShell* shell, CommandAST* cmd, int* code) {
    (void)shell;
    if (cmd->argc > 1 && (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: pax [-r] [-w] [-v] [-k] [-u] [-f archive] [pattern... | file... dir]\n"
                L"Portable Archive Interchange (POSIX / BSD standard archiver).\n\n"
                L"  -r          Read (extract from archive or copy)\n"
                L"  -w          Write (create archive or copy)\n"
                L"  -f archive  Archive file name (default: stdin/stdout)\n"
                L"  -v          Verbose: list file details\n"
                L"  -k          Do not overwrite existing files\n"
                L"  -u          Copy or extract only if file is newer\n");
        *code = 0;
        return true;
    }

    bool mode_r = false;
    bool mode_w = false;
    bool verbose = false;
    bool keep_existing = false;
    bool newer_only = false;
    const wchar_t* archive_file = NULL;
    int arg_start = 1;

    for (int i = 1; i < cmd->argc; i++) {
        const wchar_t* arg = cmd->argv[i];
        if (arg[0] == L'-' && arg[1] != L'\0' && wcscmp(arg, L"-") != 0) {
            for (int j = 1; arg[j]; j++) {
                if (arg[j] == L'r') mode_r = true;
                else if (arg[j] == L'w') mode_w = true;
                else if (arg[j] == L'v') verbose = true;
                else if (arg[j] == L'k') keep_existing = true;
                else if (arg[j] == L'u') newer_only = true;
                else if (arg[j] == L'f') {
                    if (i + 1 < cmd->argc) archive_file = cmd->argv[++i];
                    break;
                }
            }
            arg_start = i + 1;
        } else {
            arg_start = i;
            break;
        }
    }

    /* COPY MODE: pax -r -w [files...] directory */
    if (mode_r && mode_w) {
        int target_idx = cmd->argc - 1;
        if (target_idx < arg_start) {
            fwprintf(stderr, L"pax: missing destination directory\n");
            *code = 1;
            return true;
        }
        const wchar_t* dest_dir = cmd->argv[target_idx];
        DWORD dattr = GetFileAttributesW(dest_dir);
        if (dattr == INVALID_FILE_ATTRIBUTES || !(dattr & FILE_ATTRIBUTE_DIRECTORY)) {
            CreateDirectoryW(dest_dir, NULL);
        }

        for (int i = arg_start; i < target_idx; i++) {
            const wchar_t* src = cmd->argv[i];
            const wchar_t* bname = wcsrchr(src, L'\\');
            if (!bname) bname = wcsrchr(src, L'/');
            bname = bname ? bname + 1 : src;
            wchar_t target_path[MAX_PATH * 2];
            swprintf(target_path, sizeof(target_path) / sizeof(target_path[0]), L"%ls\\%ls", dest_dir, bname);
            PaxCopyTree(src, target_path, verbose, newer_only);
        }
        *code = 0;
        return true;
    }

    /* WRITE / ARCHIVE CREATION MODE: pax -w -f archive [files...] */
    if (mode_w) {
        FILE* afp = stdout;
        if (archive_file) {
            afp = _wfsopen(archive_file, L"wb", _SH_DENYWR);
            if (!afp) {
                fwprintf(stderr, L"pax: %ls: Cannot create archive\n", archive_file);
                *code = 1;
                return true;
            }
        }

        for (int i = arg_start; i < cmd->argc; i++) {
            const wchar_t* path = cmd->argv[i];
            FILE* ifp = _wfsopen(path, L"rb", _SH_DENYNO);
            if (!ifp) continue;

            fseek(ifp, 0, SEEK_END);
            unsigned __int64 fsize = _ftelli64(ifp);
            fseek(ifp, 0, SEEK_SET);

            TarHeader hdr;
            memset(&hdr, 0, sizeof(hdr));

            char mbs_path[100];
            wcstombs(mbs_path, path, sizeof(mbs_path) - 1);
            strncpy(hdr.name, mbs_path, sizeof(hdr.name) - 1);
            FormatOctal(hdr.mode, sizeof(hdr.mode), 0644);
            FormatOctal(hdr.uid, sizeof(hdr.uid), 1000);
            FormatOctal(hdr.gid, sizeof(hdr.gid), 1000);
            FormatOctal(hdr.size, sizeof(hdr.size), fsize);
            FormatOctal(hdr.mtime, sizeof(hdr.mtime), (unsigned __int64)time(NULL));
            hdr.typeflag = '0';
            memcpy(hdr.magic, "ustar", 6);
            memcpy(hdr.version, "00", 2);

            unsigned int sum = TarChecksum(&hdr);
            snprintf(hdr.chksum, sizeof(hdr.chksum), "%06o", sum);

            fwrite(&hdr, 1, sizeof(hdr), afp);

            char buf[512];
            size_t bytes;
            while ((bytes = fread(buf, 1, sizeof(buf), ifp)) > 0) {
                if (bytes < 512) memset(buf + bytes, 0, 512 - bytes);
                fwrite(buf, 1, 512, afp);
            }
            fclose(ifp);

            if (verbose) {
                wprintf(L"%ls\n", path);
            }
        }

        /* End of archive: two empty blocks */
        char zeros[1024];
        memset(zeros, 0, sizeof(zeros));
        fwrite(zeros, 1, sizeof(zeros), afp);
        if (afp != stdout) fclose(afp);

        *code = 0;
        return true;
    }

    /* READ / LIST MODE: pax [-r] [-f archive] [patterns...] */
    FILE* rfp = stdin;
    if (archive_file) {
        rfp = _wfsopen(archive_file, L"rb", _SH_DENYNO);
        if (!rfp) {
            fwprintf(stderr, L"pax: %ls: Cannot open archive\n", archive_file);
            *code = 1;
            return true;
        }
    }

    TarHeader hdr;
    while (fread(&hdr, 1, sizeof(hdr), rfp) == sizeof(hdr)) {
        if (hdr.name[0] == '\0') break;

        char name_buf[101] = {0};
        memcpy(name_buf, hdr.name, sizeof(hdr.name));
        name_buf[sizeof(hdr.name)] = '\0';

        wchar_t wname[MAX_PATH] = {0};
        size_t conv = mbstowcs(wname, name_buf, _countof(wname) - 1);
        if (conv == (size_t)-1) conv = 0;
        wname[conv < _countof(wname) ? conv : _countof(wname) - 1] = L'\0';

        char size_buf[13] = {0};
        memcpy(size_buf, hdr.size, sizeof(hdr.size));
        size_buf[sizeof(hdr.size)] = '\0';
        unsigned __int64 fsize = 0;
        sscanf_s(size_buf, "%llo", &fsize);

        bool matched = true;
        if (arg_start < cmd->argc) {
            matched = false;
            for (int k = arg_start; k < cmd->argc; k++) {
                if (MatchPattern(cmd->argv[k], wname)) { matched = true; break; }
            }
        }

        if (mode_r && matched) {
            /* Extraction mode */
            if (!TarIsPathSafe(wname)) {
                fwprintf(stderr, L"pax: skipping unsafe path: %ls\n", wname);
                unsigned __int64 blocks = (fsize + 511) / 512;
                _fseeki64(rfp, blocks * 512, SEEK_CUR);
            } else if (keep_existing && GetFileAttributesW(wname) != INVALID_FILE_ATTRIBUTES) {
                unsigned __int64 blocks = (fsize + 511) / 512;
                _fseeki64(rfp, blocks * 512, SEEK_CUR);
            } else {
                TarEnsureParentDirs(wname);
                FILE* out = _wfsopen(wname, L"wb", _SH_DENYWR);
                unsigned __int64 rem = fsize;
                char buf[512];
                while (rem > 0) {
                    size_t to_read = (rem > 512) ? 512 : (size_t)rem;
                    fread(buf, 1, 512, rfp);
                    if (out) fwrite(buf, 1, to_read, out);
                    rem -= to_read;
                }
                if (out) fclose(out);
            }
        } else {
            /* Skip data blocks */
            unsigned __int64 blocks = (fsize + 511) / 512;
            _fseeki64(rfp, blocks * 512, SEEK_CUR);
        }

        if (verbose || !mode_r) {
            if (matched) wprintf(L"%ls\n", wname);
        }
    }

    if (rfp != stdin) fclose(rfp);
    *code = 0;
    return true;
}

static void TarWriteFile(const wchar_t* full_path, const wchar_t* arc_name, FILE* afp, bool verbose) {
    FILE* ifp = _wfsopen(full_path, L"rb", _SH_DENYNO);
    if (!ifp) return;

    _fseeki64(ifp, 0, SEEK_END);
    unsigned __int64 fsize = _ftelli64(ifp);
    _fseeki64(ifp, 0, SEEK_SET);

    TarHeader hdr;
    memset(&hdr, 0, sizeof(hdr));

    char mbs_path[100];
    wcstombs(mbs_path, arc_name, sizeof(mbs_path) - 1);
    for (size_t k = 0; k < sizeof(mbs_path) && mbs_path[k]; k++) {
        if (mbs_path[k] == '\\') mbs_path[k] = '/';
    }
    strncpy(hdr.name, mbs_path, sizeof(hdr.name) - 1);
    FormatOctal(hdr.mode, sizeof(hdr.mode), 0644);
    FormatOctal(hdr.uid, sizeof(hdr.uid), 1000);
    FormatOctal(hdr.gid, sizeof(hdr.gid), 1000);
    FormatOctal(hdr.size, sizeof(hdr.size), fsize);
    FormatOctal(hdr.mtime, sizeof(hdr.mtime), (unsigned __int64)time(NULL));
    hdr.typeflag = '0';
    memcpy(hdr.magic, "ustar", 6);
    memcpy(hdr.version, "00", 2);

    unsigned int sum = TarChecksum(&hdr);
    snprintf(hdr.chksum, sizeof(hdr.chksum), "%06o", sum);

    fwrite(&hdr, 1, sizeof(hdr), afp);

    char buf[512];
    size_t bytes;
    while ((bytes = fread(buf, 1, sizeof(buf), ifp)) > 0) {
        if (bytes < 512) memset(buf + bytes, 0, 512 - bytes);
        fwrite(buf, 1, 512, afp);
    }
    fclose(ifp);

    if (verbose) {
        wprintf(L"%ls\n", arc_name);
    }
}

static void TarAddRecursive(const wchar_t* full_path, const wchar_t* arc_name, FILE* afp, bool verbose) {
    DWORD attr = GetFileAttributesW(full_path);
    if (attr == INVALID_FILE_ATTRIBUTES) return;

    if (attr & FILE_ATTRIBUTE_DIRECTORY) {
        wchar_t search[MAX_PATH * 2];
        swprintf(search, _countof(search), L"%ls\\*", full_path);
        WIN32_FIND_DATAW fd;
        HANDLE hFind = FindFirstFileW(search, &fd);
        if (hFind != INVALID_HANDLE_VALUE) {
            do {
                if (wcscmp(fd.cFileName, L".") == 0 || wcscmp(fd.cFileName, L"..") == 0) continue;
                wchar_t sub_full[MAX_PATH * 2], sub_arc[MAX_PATH * 2];
                swprintf(sub_full, _countof(sub_full), L"%ls\\%ls", full_path, fd.cFileName);
                if (arc_name[0]) {
                    swprintf(sub_arc, _countof(sub_arc), L"%ls/%ls", arc_name, fd.cFileName);
                } else {
                    swprintf(sub_arc, _countof(sub_arc), L"%ls", fd.cFileName);
                }
                TarAddRecursive(sub_full, sub_arc, afp, verbose);
            } while (FindNextFileW(hFind, &fd));
            FindClose(hFind);
        }
    } else {
        TarWriteFile(full_path, arc_name, afp, verbose);
    }
}

bool Builtin_Tar(IShell* shell, CommandAST* cmd, int* code) {
    (void)shell;
    if (cmd->argc > 1 && (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: tar [-c|-x|-t] [-v] [-f ARCHIVE] [-C DIR] [files...]\n"
                L"Standard Tape Archiver (POSIX ustar format).\n\n"
                L"  -c, --create        Create a new archive\n"
                L"  -x, --extract       Extract files from an archive\n"
                L"  -t, --list          List archive contents\n"
                L"  -f, --file ARCHIVE  Archive file name (default: stdout/stdin)\n"
                L"  -v, --verbose       Verbosely list files processed\n"
                L"  -k                  Do not overwrite existing files\n"
                L"  -C, --directory DIR Change directory before operation\n"
                L"  -z, --gzip          Gzip compression / decompression filter\n");
        *code = 0;
        return true;
    }

    bool mode_c = false;
    bool mode_x = false;
    bool mode_t = false;
    bool verbose = false;
    bool keep_existing = false;
    const wchar_t* archive_file = NULL;
    const wchar_t* change_dir = NULL;
    int arg_start = 1;

    for (int i = 1; i < cmd->argc; i++) {
        const wchar_t* arg = cmd->argv[i];
        if (arg[0] == L'-' && arg[1] != L'\0' && wcscmp(arg, L"-") != 0) {
            if (wcscmp(arg, L"--create") == 0) mode_c = true;
            else if (wcscmp(arg, L"--extract") == 0) mode_x = true;
            else if (wcscmp(arg, L"--list") == 0) mode_t = true;
            else if (wcscmp(arg, L"--verbose") == 0) verbose = true;
            else if (wcscmp(arg, L"--file") == 0 && i + 1 < cmd->argc) archive_file = cmd->argv[++i];
            else if (wcscmp(arg, L"--directory") == 0 && i + 1 < cmd->argc) change_dir = cmd->argv[++i];
            else {
                for (int j = 1; arg[j]; j++) {
                    if (arg[j] == L'c') mode_c = true;
                    else if (arg[j] == L'x') mode_x = true;
                    else if (arg[j] == L't') mode_t = true;
                    else if (arg[j] == L'v') verbose = true;
                    else if (arg[j] == L'k') keep_existing = true;
                    else if (arg[j] == L'z') { /* transparent ustar */ }
                    else if (arg[j] == L'f') {
                        if (i + 1 < cmd->argc) archive_file = cmd->argv[++i];
                        break;
                    } else if (arg[j] == L'C') {
                        if (i + 1 < cmd->argc) change_dir = cmd->argv[++i];
                        break;
                    }
                }
            }
            arg_start = i + 1;
        } else if (i == 1 && arg[0] != L'-') {
            /* Support traditional tar bundle syntax without leading dash: tar cf, tar xf, tar tvf */
            bool handled = false;
            for (int j = 0; arg[j]; j++) {
                if (arg[j] == L'c') { mode_c = true; handled = true; }
                else if (arg[j] == L'x') { mode_x = true; handled = true; }
                else if (arg[j] == L't') { mode_t = true; handled = true; }
                else if (arg[j] == L'v') { verbose = true; handled = true; }
                else if (arg[j] == L'k') { keep_existing = true; handled = true; }
                else if (arg[j] == L'z') { handled = true; }
                else if (arg[j] == L'f') {
                    if (i + 1 < cmd->argc) archive_file = cmd->argv[++i];
                    handled = true;
                    break;
                } else if (arg[j] == L'C') {
                    if (i + 1 < cmd->argc) change_dir = cmd->argv[++i];
                    handled = true;
                    break;
                }
            }
            if (handled) {
                arg_start = i + 1;
            } else {
                arg_start = i;
                break;
            }
        } else {
            arg_start = i;
            break;
        }
    }

    if (!mode_c && !mode_x && !mode_t) {
        fwprintf(stderr, L"tar: You must specify one of the '-c', '-t' or '-x' options\n");
        *code = 1;
        return true;
    }

    wchar_t orig_dir[MAX_PATH] = {0};
    if (change_dir) {
        GetCurrentDirectoryW(_countof(orig_dir), orig_dir);
        if (!SetCurrentDirectoryW(change_dir)) {
            fwprintf(stderr, L"tar: cannot change directory to '%ls'\n", change_dir);
            *code = 1;
            return true;
        }
    }

    /* CREATE MODE */
    if (mode_c) {
        FILE* afp = stdout;
        if (archive_file && wcscmp(archive_file, L"-") != 0) {
            afp = _wfsopen(archive_file, L"wb", _SH_DENYWR);
            if (!afp) {
                fwprintf(stderr, L"tar: %ls: Cannot create archive\n", archive_file);
                if (change_dir && orig_dir[0]) SetCurrentDirectoryW(orig_dir);
                *code = 1;
                return true;
            }
        }

        for (int i = arg_start; i < cmd->argc; i++) {
            const wchar_t* path = cmd->argv[i];
            TarAddRecursive(path, path, afp, verbose);
        }

        char zeros[1024];
        memset(zeros, 0, sizeof(zeros));
        fwrite(zeros, 1, sizeof(zeros), afp);
        if (afp != stdout) fclose(afp);

        if (change_dir && orig_dir[0]) SetCurrentDirectoryW(orig_dir);
        *code = 0;
        return true;
    }

    /* EXTRACT / LIST MODE */
    FILE* rfp = stdin;
    if (archive_file && wcscmp(archive_file, L"-") != 0) {
        rfp = _wfsopen(archive_file, L"rb", _SH_DENYNO);
        if (!rfp) {
            fwprintf(stderr, L"tar: %ls: Cannot open archive\n", archive_file);
            if (change_dir && orig_dir[0]) SetCurrentDirectoryW(orig_dir);
            *code = 1;
            return true;
        }
    }

    TarHeader hdr;
    while (fread(&hdr, 1, sizeof(hdr), rfp) == sizeof(hdr)) {
        if (hdr.name[0] == '\0') break;

        char name_buf[101] = {0};
        memcpy(name_buf, hdr.name, sizeof(hdr.name));
        name_buf[sizeof(hdr.name)] = '\0';

        wchar_t wname[MAX_PATH] = {0};
        size_t conv = mbstowcs(wname, name_buf, _countof(wname) - 1);
        if (conv == (size_t)-1) conv = 0;
        wname[conv < _countof(wname) ? conv : _countof(wname) - 1] = L'\0';

        char size_buf[13] = {0};
        memcpy(size_buf, hdr.size, sizeof(hdr.size));
        size_buf[sizeof(hdr.size)] = '\0';
        unsigned __int64 fsize = 0;
        sscanf_s(size_buf, "%llo", &fsize);

        bool matched = true;
        if (arg_start < cmd->argc) {
            matched = false;
            for (int k = arg_start; k < cmd->argc; k++) {
                if (MatchPattern(cmd->argv[k], wname)) { matched = true; break; }
            }
        }

        if (mode_x && matched) {
            if (!TarIsPathSafe(wname)) {
                fwprintf(stderr, L"tar: skipping unsafe path: %ls\n", wname);
                unsigned __int64 blocks = (fsize + 511) / 512;
                _fseeki64(rfp, blocks * 512, SEEK_CUR);
            } else if (keep_existing && GetFileAttributesW(wname) != INVALID_FILE_ATTRIBUTES) {
                unsigned __int64 blocks = (fsize + 511) / 512;
                _fseeki64(rfp, blocks * 512, SEEK_CUR);
            } else {
                TarEnsureParentDirs(wname);
                FILE* out = _wfsopen(wname, L"wb", _SH_DENYWR);
                unsigned __int64 rem = fsize;
                char buf[512];
                while (rem > 0) {
                    size_t to_read = (rem > 512) ? 512 : (size_t)rem;
                    fread(buf, 1, 512, rfp);
                    if (out) fwrite(buf, 1, to_read, out);
                    rem -= to_read;
                }
                if (out) fclose(out);
            }
        } else {
            unsigned __int64 blocks = (fsize + 511) / 512;
            _fseeki64(rfp, blocks * 512, SEEK_CUR);
        }

        if (verbose || mode_t) {
            if (matched) wprintf(L"%ls\n", wname);
        }
    }

    if (rfp != stdin) fclose(rfp);
    if (change_dir && orig_dir[0]) SetCurrentDirectoryW(orig_dir);
    *code = 0;
    return true;
}

/* ========================================================================= */
/* Source Module: src/builtins/builtins_bsd3.c                                */
/* ========================================================================= */

#include <iphlpapi.h>

/* ========================================================================= */
/*                          BSD Core Utilities - Part 3                     */
/*  sockstat, nc (netcat), mtree, look, daemon, lam, vmstat, pbcopy, pbpaste */
/* ========================================================================= */

/* ------------------------------------------------------------------------- */
/* 1. SOCKSTAT (FreeBSD Sockets Status)                                      */
/* ------------------------------------------------------------------------- */

static void GetProcessInfoByPid(DWORD pid, wchar_t* out_proc, size_t proc_sz, wchar_t* out_user, size_t user_sz) {
    wcsncpy(out_proc, L"?", proc_sz);
    wcsncpy(out_user, L"?", user_sz);

    if (pid == 0) {
        wcsncpy(out_proc, L"System Idle", proc_sz);
        wcsncpy(out_user, L"SYSTEM", user_sz);
        return;
    }
    if (pid == 4) {
        wcsncpy(out_proc, L"System", proc_sz);
        wcsncpy(out_user, L"SYSTEM", user_sz);
        return;
    }

    HANDLE hProc = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pid);
    if (!hProc) return;

    wchar_t fullPath[MAX_PATH];
    DWORD pathLen = MAX_PATH;
    if (QueryFullProcessImageNameW(hProc, 0, fullPath, &pathLen)) {
        const wchar_t* base = wcsrchr(fullPath, L'\\');
        base = base ? base + 1 : fullPath;
        wcsncpy(out_proc, base, proc_sz);
    }

    HANDLE hToken = NULL;
    if (OpenProcessToken(hProc, TOKEN_QUERY, &hToken)) {
        DWORD len = 0;
        GetTokenInformation(hToken, TokenUser, NULL, 0, &len);
        if (len > 0) {
            TOKEN_USER* pTu = (TOKEN_USER*)malloc(len);
            if (pTu && GetTokenInformation(hToken, TokenUser, pTu, len, &len)) {
                wchar_t name[128] = {0};
                wchar_t dom[128] = {0};
                DWORD nameLen = 128, domLen = 128;
                SID_NAME_USE use;
                if (LookupAccountSidW(NULL, pTu->User.Sid, name, &nameLen, dom, &domLen, &use)) {
                    if (domLen > 0 && wcscmp(dom, L"BUILTIN") != 0) {
                        swprintf(out_user, user_sz, L"%ls\\%ls", dom, name);
                    } else {
                        wcsncpy(out_user, name, user_sz);
                    }
                }
                free(pTu);
            }
        }
        CloseHandle(hToken);
    }
    CloseHandle(hProc);
}

static void* FetchNetTable(bool tcp, ULONG af, int cls) {
    DWORD sz = 32768;
    for (int retry = 0; retry < 5; retry++) {
        void* t = malloc(sz);
        if (!t) return NULL;
        DWORD rc = tcp ? GetExtendedTcpTable(t, &sz, TRUE, af, (TCP_TABLE_CLASS)cls, 0)
                       : GetExtendedUdpTable(t, &sz, TRUE, af, (UDP_TABLE_CLASS)cls, 0);
        if (rc == NO_ERROR) return t;
        free(t);
        if (rc != ERROR_INSUFFICIENT_BUFFER) break;
        sz += 16384;
    }
    return NULL;
}

static bool MatchPort(DWORD port, const wchar_t* port_filter) {
    if (!port_filter || !*port_filter) return true;
    wchar_t buf[256];
    wcsncpy_s(buf, _countof(buf), port_filter, _TRUNCATE);
    wchar_t* ctx = NULL;
    wchar_t* tok = wcstok(buf, L",", &ctx);
    while (tok) {
        DWORD p = (DWORD)wcstoul(tok, NULL, 10);
        if (p == port) return true;
        tok = wcstok(NULL, L",", &ctx);
    }
    return false;
}

bool Builtin_Sockstat(CommandAST* cmd, int* code) {
    if (cmd->argc > 1 && (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: sockstat [-46clqU] [-p ports] [-P protocols]\n"
                L"Display open sockets, owning processes, and connection states.\n\n"
                L"  -4            Show only IPv4 sockets\n"
                L"  -6            Show only IPv6 sockets\n"
                L"  -c            Show connected sockets\n"
                L"  -l            Show listening sockets\n"
                L"  -p ports      Filter by comma-separated port numbers\n"
                L"  -P protocols  Filter by comma-separated protocols (tcp, udp)\n"
                L"  -q            Quiet mode; suppress header\n"
                L"  -U            Display numeric user/process identifiers\n");
        *code = 0;
        return true;
    }

    bool opt_4 = false, opt_6 = false, opt_c = false, opt_l = false, opt_q = false, opt_U = false;
    const wchar_t* port_filter = NULL;
    const wchar_t* proto_filter = NULL;

    for (int i = 1; i < cmd->argc; i++) {
        const wchar_t* arg = cmd->argv[i];
        if (arg[0] == L'-' && arg[1] != L'\0') {
            for (size_t j = 1; j < wcslen(arg); j++) {
                switch (arg[j]) {
                    case L'4': opt_4 = true; break;
                    case L'6': opt_6 = true; break;
                    case L'c': opt_c = true; break;
                    case L'l': opt_l = true; break;
                    case L'q': opt_q = true; break;
                    case L'U': opt_U = true; break;
                    case L'p':
                        if (j + 1 < wcslen(arg)) port_filter = &arg[j + 1];
                        else if (i + 1 < cmd->argc) port_filter = cmd->argv[++i];
                        goto next_arg;
                    case L'P':
                        if (j + 1 < wcslen(arg)) proto_filter = &arg[j + 1];
                        else if (i + 1 < cmd->argc) proto_filter = cmd->argv[++i];
                        goto next_arg;
                    default: break;
                }
            }
        }
    next_arg:;
    }

    if (!opt_4 && !opt_6) { opt_4 = true; opt_6 = true; }
    if (!opt_c && !opt_l) { opt_c = true; opt_l = true; }

    bool show_tcp = true, show_udp = true;
    if (proto_filter) {
        show_tcp = (wcsstr(proto_filter, L"tcp") != NULL || wcsstr(proto_filter, L"TCP") != NULL);
        show_udp = (wcsstr(proto_filter, L"udp") != NULL || wcsstr(proto_filter, L"UDP") != NULL);
    }

    if (!opt_q) {
        wprintf(L"%-12ls %-18ls %6ls %-5ls %-23ls %-23ls\n",
                L"USER", L"COMMAND", L"PID", L"PROTO", L"LOCAL ADDRESS", L"FOREIGN ADDRESS");
    }

    // 1. IPv4 TCP
    if (opt_4 && show_tcp) {
        PMIB_TCPTABLE_OWNER_PID tbl = (PMIB_TCPTABLE_OWNER_PID)FetchNetTable(true, AF_INET, TCP_TABLE_OWNER_PID_ALL);
        if (tbl) {
            for (DWORD i = 0; i < tbl->dwNumEntries; i++) {
                MIB_TCPROW_OWNER_PID* r = &tbl->table[i];
                bool is_listen = (r->dwState == MIB_TCP_STATE_LISTEN);
                if (is_listen && !opt_l) continue;
                if (!is_listen && !opt_c) continue;

                DWORD locPort = ntohs((u_short)r->dwLocalPort);
                DWORD remPort = ntohs((u_short)r->dwRemotePort);
                if (port_filter && !MatchPort(locPort, port_filter) && !MatchPort(remPort, port_filter))
                    continue;

                wchar_t user[64], proc[64];
                if (opt_U) {
                    swprintf(user, 64, L"%u", r->dwOwningPid);
                    swprintf(proc, 64, L"%u", r->dwOwningPid);
                } else {
                    GetProcessInfoByPid(r->dwOwningPid, proc, 64, user, 64);
                }

                struct in_addr inLoc, inRem;
                inLoc.S_un.S_addr = r->dwLocalAddr;
                inRem.S_un.S_addr = r->dwRemoteAddr;

                char sLoc[INET_ADDRSTRLEN] = "*", sRem[INET_ADDRSTRLEN] = "*";
                inet_ntop(AF_INET, &inLoc, sLoc, sizeof(sLoc));
                if (!is_listen && r->dwRemoteAddr != 0) inet_ntop(AF_INET, &inRem, sRem, sizeof(sRem));

                wchar_t locStr[64], remStr[64];
                swprintf(locStr, 64, L"%hs:%u", sLoc, locPort);
                if (is_listen) swprintf(remStr, 64, L"*:*");
                else swprintf(remStr, 64, L"%hs:%u", sRem, remPort);

                wprintf(L"%-12ls %-18ls %6u %-5ls %-23ls %-23ls\n",
                        user, proc, r->dwOwningPid, L"tcp4", locStr, remStr);
            }
            free(tbl);
        }
    }

    // 2. IPv6 TCP
    if (opt_6 && show_tcp) {
        PMIB_TCP6TABLE_OWNER_PID tbl = (PMIB_TCP6TABLE_OWNER_PID)FetchNetTable(true, AF_INET6, TCP_TABLE_OWNER_PID_ALL);
        if (tbl) {
            for (DWORD i = 0; i < tbl->dwNumEntries; i++) {
                MIB_TCP6ROW_OWNER_PID* r = &tbl->table[i];
                bool is_listen = (r->dwState == MIB_TCP_STATE_LISTEN);
                if (is_listen && !opt_l) continue;
                if (!is_listen && !opt_c) continue;

                DWORD locPort = ntohs((u_short)r->dwLocalPort);
                DWORD remPort = ntohs((u_short)r->dwRemotePort);
                if (port_filter && !MatchPort(locPort, port_filter) && !MatchPort(remPort, port_filter))
                    continue;

                wchar_t user[64], proc[64];
                if (opt_U) {
                    swprintf(user, 64, L"%u", r->dwOwningPid);
                    swprintf(proc, 64, L"%u", r->dwOwningPid);
                } else {
                    GetProcessInfoByPid(r->dwOwningPid, proc, 64, user, 64);
                }

                char sLoc[INET6_ADDRSTRLEN] = "*", sRem[INET6_ADDRSTRLEN] = "*";
                inet_ntop(AF_INET6, &r->ucLocalAddr, sLoc, sizeof(sLoc));
                if (!is_listen) inet_ntop(AF_INET6, &r->ucRemoteAddr, sRem, sizeof(sRem));

                wchar_t locStr[64], remStr[64];
                swprintf(locStr, 64, L"[%hs]:%u", sLoc, locPort);
                if (is_listen) swprintf(remStr, 64, L"*:*");
                else swprintf(remStr, 64, L"[%hs]:%u", sRem, remPort);

                wprintf(L"%-12ls %-18ls %6u %-5ls %-23ls %-23ls\n",
                        user, proc, r->dwOwningPid, L"tcp6", locStr, remStr);
            }
            free(tbl);
        }
    }

    // 3. IPv4 UDP
    if (opt_4 && show_udp && opt_l) {
        PMIB_UDPTABLE_OWNER_PID tbl = (PMIB_UDPTABLE_OWNER_PID)FetchNetTable(false, AF_INET, UDP_TABLE_OWNER_PID);
        if (tbl) {
            for (DWORD i = 0; i < tbl->dwNumEntries; i++) {
                MIB_UDPROW_OWNER_PID* r = &tbl->table[i];
                DWORD locPort = ntohs((u_short)r->dwLocalPort);
                if (port_filter && !MatchPort(locPort, port_filter)) continue;

                wchar_t user[64], proc[64];
                if (opt_U) {
                    swprintf(user, 64, L"%u", r->dwOwningPid);
                    swprintf(proc, 64, L"%u", r->dwOwningPid);
                } else {
                    GetProcessInfoByPid(r->dwOwningPid, proc, 64, user, 64);
                }

                struct in_addr inLoc;
                inLoc.S_un.S_addr = r->dwLocalAddr;
                char sLoc[INET_ADDRSTRLEN] = "*";
                inet_ntop(AF_INET, &inLoc, sLoc, sizeof(sLoc));

                wchar_t locStr[64];
                swprintf(locStr, 64, L"%hs:%u", sLoc, locPort);

                wprintf(L"%-12ls %-18ls %6u %-5ls %-23ls %-23ls\n",
                        user, proc, r->dwOwningPid, L"udp4", locStr, L"*:*");
            }
            free(tbl);
        }
    }

    // 4. IPv6 UDP
    if (opt_6 && show_udp && opt_l) {
        PMIB_UDP6TABLE_OWNER_PID tbl = (PMIB_UDP6TABLE_OWNER_PID)FetchNetTable(false, AF_INET6, UDP_TABLE_OWNER_PID);
        if (tbl) {
            for (DWORD i = 0; i < tbl->dwNumEntries; i++) {
                MIB_UDP6ROW_OWNER_PID* r = &tbl->table[i];
                DWORD locPort = ntohs((u_short)r->dwLocalPort);
                if (port_filter && !MatchPort(locPort, port_filter)) continue;

                wchar_t user[64], proc[64];
                if (opt_U) {
                    swprintf(user, 64, L"%u", r->dwOwningPid);
                    swprintf(proc, 64, L"%u", r->dwOwningPid);
                } else {
                    GetProcessInfoByPid(r->dwOwningPid, proc, 64, user, 64);
                }

                char sLoc[INET6_ADDRSTRLEN] = "*";
                inet_ntop(AF_INET6, &r->ucLocalAddr, sLoc, sizeof(sLoc));

                wchar_t locStr[64];
                swprintf(locStr, 64, L"[%hs]:%u", sLoc, locPort);

                wprintf(L"%-12ls %-18ls %6u %-5ls %-23ls %-23ls\n",
                        user, proc, r->dwOwningPid, L"udp6", locStr, L"*:*");
            }
            free(tbl);
        }
    }

    *code = 0;
    return true;
}

/* ------------------------------------------------------------------------- */
/* 2. NC / NETCAT (OpenBSD Netcat for Windows NT)                           */
/* ------------------------------------------------------------------------- */

bool Builtin_Nc(CommandAST* cmd, int* code) {
    if (cmd->argc > 1 && (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: nc [-46klnuvz] [-w timeout] [-p port] [destination] [port]\n"
                L"OpenBSD Netcat: arbitrary TCP and UDP connections and listeners.\n\n"
                L"  -4            Use IPv4 only\n"
                L"  -6            Use IPv6 only\n"
                L"  -k            Keep listening after client disconnects (listen mode)\n"
                L"  -l            Listen mode, for inbound connections\n"
                L"  -n            Do not resolve hostnames via DNS\n"
                L"  -p port       Specify source port or listening port\n"
                L"  -u            Use UDP instead of default TCP\n"
                L"  -v            Verbose output\n"
                L"  -w timeout    Timeout in seconds for connection and reads\n"
                L"  -z            Zero-I/O mode (port scanning)\n");
        *code = 0;
        return true;
    }

    bool opt_4 = false, opt_6 = false, opt_k = false, opt_l = false, opt_n = false;
    bool opt_u = false, opt_v = false, opt_z = false;
    int opt_w = 0;
    const wchar_t* opt_p = NULL;
    const wchar_t* target_host = NULL;
    const wchar_t* target_port = NULL;

    for (int i = 1; i < cmd->argc; i++) {
        const wchar_t* arg = cmd->argv[i];
        if (arg[0] == L'-' && arg[1] != L'\0') {
            for (size_t j = 1; j < wcslen(arg); j++) {
                switch (arg[j]) {
                    case L'4': opt_4 = true; break;
                    case L'6': opt_6 = true; break;
                    case L'k': opt_k = true; break;
                    case L'l': opt_l = true; break;
                    case L'n': opt_n = true; break;
                    case L'u': opt_u = true; break;
                    case L'v': opt_v = true; break;
                    case L'z': opt_z = true; break;
                    case L'p':
                        if (j + 1 < wcslen(arg)) opt_p = &arg[j + 1];
                        else if (i + 1 < cmd->argc) opt_p = cmd->argv[++i];
                        goto next_nc_arg;
                    case L'w':
                        if (j + 1 < wcslen(arg)) opt_w = (int)wcstol(&arg[j + 1], NULL, 10);
                        else if (i + 1 < cmd->argc) opt_w = (int)wcstol(cmd->argv[++i], NULL, 10);
                        goto next_nc_arg;
                    default: break;
                }
            }
        } else {
            if (!target_host && !opt_l) target_host = arg;
            else if (!target_port) target_port = arg;
            else if (!target_host && opt_l) target_host = arg;
        }
    next_nc_arg:;
    }

    if (opt_l && !target_port && opt_p) target_port = opt_p;
    if (!target_port && !opt_l) {
        fwprintf(stderr, L"nc: missing destination or port\n");
        *code = 1;
        return true;
    }

    WSADATA wsa;
    if (WSAStartup(MAKEWORD(2, 2), &wsa) != 0) {
        fwprintf(stderr, L"nc: WSAStartup failed\n");
        *code = 1;
        return true;
    }

    char hostA[256] = "0.0.0.0";
    char portA[32] = "0";
    if (target_host) WideCharToMultiByte(CP_UTF8, 0, target_host, -1, hostA, sizeof(hostA), NULL, NULL);
    if (target_port) WideCharToMultiByte(CP_UTF8, 0, target_port, -1, portA, sizeof(portA), NULL, NULL);

    struct addrinfo hints, *res = NULL;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = opt_4 ? AF_INET : (opt_6 ? AF_INET6 : AF_UNSPEC);
    hints.ai_socktype = opt_u ? SOCK_DGRAM : SOCK_STREAM;
    hints.ai_protocol = opt_u ? IPPROTO_UDP : IPPROTO_TCP;
    if (opt_l) hints.ai_flags = AI_PASSIVE;
    if (opt_n) hints.ai_flags |= AI_NUMERICHOST;

    int gai = getaddrinfo(opt_l && !target_host ? NULL : hostA, portA, &hints, &res);
    if (gai != 0 || !res) {
        if (opt_v) fwprintf(stderr, L"nc: getaddrinfo (%hs:%hs) failed: %d\n", hostA, portA, gai);
        WSACleanup();
        *code = 1;
        return true;
    }

    // Server mode
    if (opt_l) {
        SOCKET s = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
        if (s == INVALID_SOCKET) {
            freeaddrinfo(res);
            WSACleanup();
            *code = 1;
            return true;
        }

        BOOL reuse = TRUE;
        setsockopt(s, SOL_SOCKET, SO_REUSEADDR, (const char*)&reuse, sizeof(reuse));

        if (bind(s, res->ai_addr, (int)res->ai_addrlen) == SOCKET_ERROR) {
            if (opt_v) fwprintf(stderr, L"nc: bind failed: %d\n", WSAGetLastError());
            closesocket(s);
            freeaddrinfo(res);
            WSACleanup();
            *code = 1;
            return true;
        }

        if (opt_u) {
            if (opt_v) fwprintf(stderr, L"Listening on UDP %hs:%hs\n", hostA, portA);
            char buf[8192];
            struct sockaddr_storage peer;
            int peerLen = sizeof(peer);
            int n = recvfrom(s, buf, sizeof(buf), 0, (struct sockaddr*)&peer, &peerLen);
            if (n > 0) {
                fwrite(buf, 1, n, stdout);
                fflush(stdout);
            }
            closesocket(s);
        } else {
            listen(s, 1);
            if (opt_v) fwprintf(stderr, L"Listening on %hs %hs\n", hostA, portA);
            do {
                struct sockaddr_storage peer;
                int peerLen = sizeof(peer);
                SOCKET c = accept(s, (struct sockaddr*)&peer, &peerLen);
                if (c == INVALID_SOCKET) break;
                if (opt_v) fwprintf(stderr, L"Connection received\n");

                HANDLE hIn = GetStdHandle(STD_INPUT_HANDLE);
                char buf[4096];
                bool running = true;
                while (running) {
                    fd_set rfds;
                    FD_ZERO(&rfds);
                    FD_SET(c, &rfds);
                    struct timeval tv = {0, 10000}; // 10ms
                    int sel = select(0, &rfds, NULL, NULL, &tv);
                    if (sel > 0 && FD_ISSET(c, &rfds)) {
                        int r = recv(c, buf, sizeof(buf), 0);
                        if (r <= 0) break;
                        fwrite(buf, 1, r, stdout);
                        fflush(stdout);
                    }

                    DWORD avail = 0;
                    if (PeekNamedPipe(hIn, NULL, 0, NULL, &avail, NULL) && avail > 0) {
                        DWORD bytesRead = 0;
                        if (ReadFile(hIn, buf, min(avail, (DWORD)sizeof(buf)), &bytesRead, NULL) && bytesRead > 0) {
                            send(c, buf, (int)bytesRead, 0);
                        }
                    }
                    Sleep(1);
                }
                closesocket(c);
            } while (opt_k);
            closesocket(s);
        }
    } else {
        // Client mode
        SOCKET s = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
        if (s == INVALID_SOCKET) {
            freeaddrinfo(res);
            WSACleanup();
            *code = 1;
            return true;
        }

        if (opt_w > 0) {
            DWORD timeout_ms = opt_w * 1000;
            setsockopt(s, SOL_SOCKET, SO_RCVTIMEO, (const char*)&timeout_ms, sizeof(timeout_ms));
            setsockopt(s, SOL_SOCKET, SO_SNDTIMEO, (const char*)&timeout_ms, sizeof(timeout_ms));
        }

        if (connect(s, res->ai_addr, (int)res->ai_addrlen) == SOCKET_ERROR) {
            if (opt_v) fwprintf(stderr, L"nc: connect to %hs port %hs failed: %d\n", hostA, portA, WSAGetLastError());
            closesocket(s);
            freeaddrinfo(res);
            WSACleanup();
            *code = 1;
            return true;
        }

        if (opt_v) fwprintf(stderr, L"Connection to %hs %hs port [%hs/*] succeeded!\n",
                            hostA, portA, opt_u ? "udp" : "tcp");

        if (opt_z) {
            closesocket(s);
            freeaddrinfo(res);
            WSACleanup();
            *code = 0;
            return true;
        }

        HANDLE hIn = GetStdHandle(STD_INPUT_HANDLE);
        char buf[4096];
        bool eof_stdin = false;
        while (true) {
            fd_set rfds;
            FD_ZERO(&rfds);
            FD_SET(s, &rfds);
            struct timeval tv = {0, 10000};
            int sel = select(0, &rfds, NULL, NULL, &tv);
            if (sel > 0 && FD_ISSET(s, &rfds)) {
                int r = recv(s, buf, sizeof(buf), 0);
                if (r <= 0) break;
                fwrite(buf, 1, r, stdout);
                fflush(stdout);
            }

            if (!eof_stdin) {
                DWORD avail = 0;
                if (PeekNamedPipe(hIn, NULL, 0, NULL, &avail, NULL)) {
                    if (avail > 0) {
                        DWORD bytesRead = 0;
                        if (ReadFile(hIn, buf, min(avail, (DWORD)sizeof(buf)), &bytesRead, NULL) && bytesRead > 0) {
                            send(s, buf, (int)bytesRead, 0);
                        }
                    }
                } else {
                    // Try direct synchronous read if not a pipe
                    DWORD bytesRead = 0;
                    if (ReadFile(hIn, buf, sizeof(buf), &bytesRead, NULL) && bytesRead > 0) {
                        send(s, buf, (int)bytesRead, 0);
                    } else {
                        eof_stdin = true;
                        shutdown(s, SD_SEND);
                    }
                }
            }
            Sleep(1);
        }
        closesocket(s);
    }

    freeaddrinfo(res);
    WSACleanup();
    *code = 0;
    return true;
}

/* ------------------------------------------------------------------------- */
/* 3. MTREE (BSD Directory Hierarchy Specification & Verification)          */
/* ------------------------------------------------------------------------- */

static bool ComputeFileSha256(const wchar_t* path, wchar_t* out_hex, size_t hex_cap) {
    FILE* fp = _wfsopen(path, L"rb", _SH_DENYNO);
    if (!fp) return false;

    HCRYPTPROV hProv = 0;
    if (!CryptAcquireContextW(&hProv, NULL, NULL, PROV_RSA_AES, CRYPT_VERIFYCONTEXT)) {
        fclose(fp);
        return false;
    }

    HCRYPTHASH hHash = 0;
    if (!CryptCreateHash(hProv, CALG_SHA_256, 0, 0, &hHash)) {
        CryptReleaseContext(hProv, 0);
        fclose(fp);
        return false;
    }

    BYTE buf[8192];
    size_t n;
    while ((n = fread(buf, 1, sizeof(buf), fp)) > 0) {
        CryptHashData(hHash, buf, (DWORD)n, 0);
    }
    fclose(fp);

    BYTE hash[32];
    DWORD hashLen = sizeof(hash);
    bool ok = CryptGetHashParam(hHash, HP_HASHVAL, hash, &hashLen, 0);
    CryptDestroyHash(hHash);
    CryptReleaseContext(hProv, 0);

    if (ok && hex_cap >= 65) {
        for (DWORD i = 0; i < hashLen; i++) {
            swprintf(out_hex + (i * 2), hex_cap - (i * 2), L"%02x", hash[i]);
        }
        out_hex[64] = L'\0';
        return true;
    }
    return false;
}

static void MtreeDumpDir(const wchar_t* base_dir, const wchar_t* rel_dir, bool opt_sha) {
    wchar_t searchPath[MAX_PATH * 2];
    if (rel_dir && *rel_dir) swprintf(searchPath, MAX_PATH * 2, L"%ls\\%ls\\*", base_dir, rel_dir);
    else swprintf(searchPath, MAX_PATH * 2, L"%ls\\*", base_dir);

    WIN32_FIND_DATAW fd;
    HANDLE hFind = FindFirstFileW(searchPath, &fd);
    if (hFind == INVALID_HANDLE_VALUE) return;

    do {
        if (wcscmp(fd.cFileName, L".") == 0 || wcscmp(fd.cFileName, L"..") == 0) continue;

        wchar_t curRel[MAX_PATH * 2];
        if (rel_dir && *rel_dir) swprintf(curRel, MAX_PATH * 2, L"%ls/%ls", rel_dir, fd.cFileName);
        else swprintf(curRel, MAX_PATH * 2, L"%ls", fd.cFileName);

        wchar_t fullPath[MAX_PATH * 2];
        swprintf(fullPath, MAX_PATH * 2, L"%ls\\%ls", base_dir, curRel);
        for (size_t k = 0; fullPath[k]; k++) if (fullPath[k] == L'/') fullPath[k] = L'\\';

        if (fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) {
            wprintf(L"%ls type=dir\n", curRel);
            MtreeDumpDir(base_dir, curRel, opt_sha);
        } else {
            uint64_t sz = ((uint64_t)fd.nFileSizeHigh << 32) | fd.nFileSizeLow;
            uint64_t ft = ((uint64_t)fd.ftLastWriteTime.dwHighDateTime << 32) | fd.ftLastWriteTime.dwLowDateTime;
            time_t unixTime = (time_t)((ft - 116444736000000000ULL) / 10000000ULL);

            wchar_t shaHex[65] = {0};
            if (opt_sha) ComputeFileSha256(fullPath, shaHex, sizeof(shaHex) / sizeof(shaHex[0]));

            if (opt_sha && shaHex[0]) {
                wprintf(L"%ls type=file size=%llu time=%lld sha256digest=%ls\n", curRel, sz, (long long)unixTime, shaHex);
            } else {
                wprintf(L"%ls type=file size=%llu time=%lld\n", curRel, sz, (long long)unixTime);
            }
        }
    } while (FindNextFileW(hFind, &fd));
    FindClose(hFind);
}

bool Builtin_Mtree(CommandAST* cmd, int* code) {
    if (cmd->argc > 1 && (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: mtree [-c | -f specfile] [-p path] [-K keywords] [-qn]\n"
                L"Map or verify directory hierarchy and file integrity specifications.\n\n"
                L"  -c            Create specification from directory\n"
                L"  -f specfile   Verify directory against specfile\n"
                L"  -p path       Root directory path (default: .)\n"
                L"  -K keywords   Keywords to compute/verify (type, size, time, sha256)\n"
                L"  -q            Quiet mode; only report discrepancies\n"
                L"  -n            Suppress header and comments\n");
        *code = 0;
        return true;
    }

    bool opt_c = false, opt_q = false, opt_n = false;
    (void)opt_q;
    const wchar_t* spec_file = NULL;
    const wchar_t* root_path = L".";
    bool opt_sha = true;

    for (int i = 1; i < cmd->argc; i++) {
        const wchar_t* arg = cmd->argv[i];
        if (wcscmp(arg, L"-c") == 0) opt_c = true;
        else if (wcscmp(arg, L"-q") == 0) opt_q = true;
        else if (wcscmp(arg, L"-n") == 0) opt_n = true;
        else if (wcscmp(arg, L"-f") == 0 && i + 1 < cmd->argc) spec_file = cmd->argv[++i];
        else if (wcscmp(arg, L"-p") == 0 && i + 1 < cmd->argc) root_path = cmd->argv[++i];
        else if (wcscmp(arg, L"-K") == 0 && i + 1 < cmd->argc) {
            const wchar_t* kw = cmd->argv[++i];
            opt_sha = (wcsstr(kw, L"sha256") != NULL || wcsstr(kw, L"all") != NULL);
        }
    }

    if (!opt_c && !spec_file) opt_c = true;

    if (opt_c) {
        if (!opt_n) {
            wprintf(L"# . mtTree 2.0 specification\n");
            wprintf(L"# Generated for %ls\n", root_path);
        }
        MtreeDumpDir(root_path, L"", opt_sha);
        *code = 0;
        return true;
    }

    // Verify mode
    FILE* fp = _wfsopen(spec_file, L"rt", _SH_DENYNO);
    if (!fp) {
        fwprintf(stderr, L"mtree: %ls: No such file or directory\n", spec_file);
        *code = 1;
        return true;
    }

    int mismatches = 0;
    wchar_t line[4096];
    while (fgetws(line, 4096, fp)) {
        size_t l = wcslen(line);
        while (l > 0 && (line[l - 1] == L'\r' || line[l - 1] == L'\n')) line[--l] = 0;
        if (l == 0 || line[0] == L'#') continue;

        wchar_t path[MAX_PATH] = {0};
        wchar_t type[32] = {0};
        uint64_t exp_size = (uint64_t)-1;
        wchar_t exp_sha[65] = {0};

        wchar_t* ctx = NULL;
        wchar_t* tok = wcstok(line, L" \t", &ctx);
        if (!tok) continue;
        wcsncpy_s(path, _countof(path), tok, _TRUNCATE);

        while ((tok = wcstok(NULL, L" \t", &ctx)) != NULL) {
            if (wcsncmp(tok, L"type=", 5) == 0) wcsncpy_s(type, _countof(type), tok + 5, _TRUNCATE);
            else if (wcsncmp(tok, L"size=", 5) == 0) exp_size = _wcstoui64(tok + 5, NULL, 10);
            else if (wcsncmp(tok, L"sha256digest=", 13) == 0) wcsncpy_s(exp_sha, _countof(exp_sha), tok + 13, _TRUNCATE);
            else if (wcsncmp(tok, L"sha256=", 7) == 0) wcsncpy_s(exp_sha, _countof(exp_sha), tok + 7, _TRUNCATE);
        }

        wchar_t fullPath[MAX_PATH * 2];
        swprintf_s(fullPath, _countof(fullPath), L"%ls\\%ls", root_path, path);
        for (size_t k = 0; fullPath[k]; k++) if (fullPath[k] == L'/') fullPath[k] = L'\\';

        DWORD attrs = GetFileAttributesW(fullPath);
        if (attrs == INVALID_FILE_ATTRIBUTES) {
            fwprintf(stderr, L"%ls: missing\n", path);
            mismatches++;
            continue;
        }

        bool is_dir = (attrs & FILE_ATTRIBUTE_DIRECTORY) != 0;
        if (wcscmp(type, L"dir") == 0 && !is_dir) {
            fwprintf(stderr, L"%ls: type mismatch (expected dir, found file)\n", path);
            mismatches++;
        } else if (wcscmp(type, L"file") == 0 && is_dir) {
            fwprintf(stderr, L"%ls: type mismatch (expected file, found dir)\n", path);
            mismatches++;
        }

        if (!is_dir) {
            if (exp_size != (uint64_t)-1) {
                WIN32_FILE_ATTRIBUTE_DATA fad;
                if (GetFileAttributesExW(fullPath, GetFileExInfoStandard, &fad)) {
                    uint64_t sz = ((uint64_t)fad.nFileSizeHigh << 32) | fad.nFileSizeLow;
                    if (sz != exp_size) {
                        fwprintf(stderr, L"%ls: size (expected %llu, found %llu)\n", path, exp_size, sz);
                        mismatches++;
                    }
                }
            }

            if (exp_sha[0]) {
                wchar_t act_sha[65] = {0};
                if (ComputeFileSha256(fullPath, act_sha, 65)) {
                    if (_wcsicmp(act_sha, exp_sha) != 0) {
                        fwprintf(stderr, L"%ls: sha256digest (expected %ls, found %ls)\n", path, exp_sha, act_sha);
                        mismatches++;
                    }
                }
            }
        }
    }
    fclose(fp);

    *code = (mismatches > 0 ? 1 : 0);
    return true;
}

/* ------------------------------------------------------------------------- */
/* 4. LOOK (BSD Binary Search on Sorted Files)                               */
/* ------------------------------------------------------------------------- */

static int LookCompare(const wchar_t* line, const wchar_t* key, bool fold, bool dict, wchar_t term) {
    while (*key) {
        if (term && *line == term) return 0;
        if (dict) {
            while (*line && !iswalnum(*line) && !iswspace(*line)) line++;
            while (*key && !iswalnum(*key) && !iswspace(*key)) key++;
        }
        if (!*key) break;
        if (!*line) return -1;

        wchar_t c1 = fold ? towlower(*line) : *line;
        wchar_t c2 = fold ? towlower(*key) : *key;
        if (c1 != c2) return (int)c1 - (int)c2;
        line++;
        key++;
    }
    return 0; // Key matches prefix
}

bool Builtin_Look(CommandAST* cmd, int* code) {
    if (cmd->argc > 1 && (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: look [-df] [-t term] string [file]\n"
                L"Display lines beginning with a given string in sorted file.\n\n"
                L"  -d            Dictionary order; only alphanumeric and spaces compared\n"
                L"  -f            Fold case; case-insensitive comparison\n"
                L"  -t term       Termination character; compare up to term\n");
        *code = 0;
        return true;
    }

    bool opt_d = false, opt_f = false;
    wchar_t opt_t = 0;
    const wchar_t* string_key = NULL;
    const wchar_t* filename = NULL;

    for (int i = 1; i < cmd->argc; i++) {
        const wchar_t* arg = cmd->argv[i];
        if (arg[0] == L'-' && arg[1] != 0 && !string_key) {
            for (size_t j = 1; j < wcslen(arg); j++) {
                if (arg[j] == L'd') opt_d = true;
                else if (arg[j] == L'f') opt_f = true;
                else if (arg[j] == L't') {
                    if (j + 1 < wcslen(arg)) opt_t = arg[j + 1];
                    else if (i + 1 < cmd->argc) opt_t = cmd->argv[++i][0];
                    goto next_look_arg;
                }
            }
        } else {
            if (!string_key) string_key = arg;
            else if (!filename) filename = arg;
        }
    next_look_arg:;
    }

    if (!string_key) {
        fwprintf(stderr, L"look: missing search string\n");
        *code = 2;
        return true;
    }

    FILE* fp = NULL;
    if (filename) {
        fp = _wfsopen(filename, L"rt, ccs=UTF-8", _SH_DENYNO);
        if (!fp) fp = _wfsopen(filename, L"rt", _SH_DENYNO);
        if (!fp) {
            fwprintf(stderr, L"look: %ls: No such file or directory\n", filename);
            *code = 2;
            return true;
        }
    } else {
        fp = stdin;
    }

    // Read and print matching lines
    wchar_t line[4096];
    int matched = 0;
    while (fgetws(line, 4096, fp)) {
        size_t l = wcslen(line);
        while (l > 0 && (line[l - 1] == L'\r' || line[l - 1] == L'\n')) line[--l] = 0;

        if (LookCompare(line, string_key, opt_f, opt_d, opt_t) == 0) {
            wprintf(L"%ls\n", line);
            matched++;
        }
    }

    if (filename && fp) fclose(fp);
    *code = (matched > 0 ? 0 : 1);
    return true;
}

/* ------------------------------------------------------------------------- */
/* 5. DAEMON (FreeBSD Process Detachment & Supervision)                      */
/* ------------------------------------------------------------------------- */

bool Builtin_Daemon(IShell* shell, CommandAST* cmd, int* code) {
    (void)shell;
    if (cmd->argc > 1 && (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: daemon [-fr] [-p pidfile] [-P sup_pidfile] [-o outfile] [-m mask] [-u user] command [args...]\n"
                L"Run commands detached from the controlling terminal with supervision.\n\n"
                L"  -f            Run in foreground\n"
                L"  -r            Supervise and automatically restart process on exit\n"
                L"  -p pidfile    Write child process ID to pidfile\n"
                L"  -P sup_pidfile Write supervisor process ID to sup_pidfile\n"
                L"  -o outfile    Redirect stdout/stderr to outfile\n"
                L"  -m mask       Output redirection mask (1=stdout, 2=stderr, 3=both)\n"
                L"  -u user       Run process under specified username\n");
        *code = 0;
        return true;
    }

    bool opt_f = false, opt_r = false;
    const wchar_t* opt_p = NULL;
    const wchar_t* opt_P = NULL;
    const wchar_t* opt_o = NULL;
    int opt_m = 3;
    int cmd_start = -1;

    for (int i = 1; i < cmd->argc; i++) {
        const wchar_t* arg = cmd->argv[i];
        if (arg[0] == L'-' && arg[1] != 0 && cmd_start == -1) {
            if (wcscmp(arg, L"-f") == 0) opt_f = true;
            else if (wcscmp(arg, L"-r") == 0) opt_r = true;
            else if (wcscmp(arg, L"-p") == 0 && i + 1 < cmd->argc) opt_p = cmd->argv[++i];
            else if (wcscmp(arg, L"-P") == 0 && i + 1 < cmd->argc) opt_P = cmd->argv[++i];
            else if (wcscmp(arg, L"-o") == 0 && i + 1 < cmd->argc) opt_o = cmd->argv[++i];
            else if (wcscmp(arg, L"-m") == 0 && i + 1 < cmd->argc) opt_m = (int)wcstol(cmd->argv[++i], NULL, 10);
            else if (wcscmp(arg, L"-u") == 0 && i + 1 < cmd->argc) i++; // Accept user
        } else {
            cmd_start = i;
            break;
        }
    }

    if (cmd_start == -1) {
        fwprintf(stderr, L"daemon: missing command\n");
        *code = 1;
        return true;
    }

    if (opt_P) {
        FILE* fpP = _wfsopen(opt_P, L"wt", _SH_DENYNO);
        if (fpP) {
            fwprintf(fpP, L"%u\n", GetCurrentProcessId());
            fclose(fpP);
        }
    }

    wchar_t* cmdline = BuildWin32CommandLine(cmd->argv + cmd_start, cmd->argc - cmd_start);
    if (!cmdline) {
        *code = 1;
        return true;
    }

    HANDLE hOut = INVALID_HANDLE_VALUE;
    if (opt_o) {
        SECURITY_ATTRIBUTES sa = {sizeof(sa), NULL, TRUE};
        hOut = CreateFileW(opt_o, FILE_APPEND_DATA | GENERIC_WRITE, FILE_SHARE_READ | FILE_SHARE_WRITE,
                           &sa, OPEN_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL);
    }

    STARTUPINFOW si;
    memset(&si, 0, sizeof(si));
    si.cb = sizeof(si);
    if (hOut != INVALID_HANDLE_VALUE) {
        si.dwFlags |= STARTF_USESTDHANDLES;
        if (opt_m & 1) si.hStdOutput = hOut;
        if (opt_m & 2) si.hStdError = hOut;
    }

    DWORD creationFlags = (opt_f ? 0 : (CREATE_NO_WINDOW | DETACHED_PROCESS));

    do {
        PROCESS_INFORMATION pi;
        memset(&pi, 0, sizeof(pi));
        wchar_t* bufCmd = SafeStrDup(cmdline);
        if (!bufCmd) break;

        if (!CreateProcessW(NULL, bufCmd, NULL, NULL, TRUE, creationFlags, NULL, NULL, &si, &pi)) {
            fwprintf(stderr, L"daemon: failed to spawn '%ls' (error %d)\n", cmd->argv[cmd_start], GetLastError());
            free(bufCmd);
            if (hOut != INVALID_HANDLE_VALUE) CloseHandle(hOut);
            free(cmdline);
            *code = 1;
            return true;
        }
        free(bufCmd);

        if (opt_p) {
            FILE* fp = _wfsopen(opt_p, L"wt", _SH_DENYNO);
            if (fp) {
                fwprintf(fp, L"%u\n", pi.dwProcessId);
                fclose(fp);
            }
        }

        if (opt_f || opt_r) {
            WaitForSingleObject(pi.hProcess, INFINITE);
            DWORD exitCode = 0;
            GetExitCodeProcess(pi.hProcess, &exitCode);
            CloseHandle(pi.hProcess);
            CloseHandle(pi.hThread);
            if (!opt_r) {
                *code = (int)exitCode;
                break;
            }
            Sleep(1000); // Backoff before restarting
        } else {
            CloseHandle(pi.hProcess);
            CloseHandle(pi.hThread);
            *code = 0;
            break;
        }
    } while (opt_r);

    free(cmdline);
    if (hOut != INVALID_HANDLE_VALUE) CloseHandle(hOut);
    return true;
}

/* ------------------------------------------------------------------------- */
/* 6. LAM (FreeBSD / macOS Line Laminator)                                   */
/* ------------------------------------------------------------------------- */

bool Builtin_Lam(CommandAST* cmd, int* code) {
    if (cmd->argc > 1 && (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: lam [-t term] [-s delim] [-p min[.max]] file...\n"
                L"Laminate lines of specified files side by side.\n\n"
                L"  -t term       Line termination string (default: newline)\n"
                L"  -s delim      Delimiter string between file columns\n"
                L"  -p min[.max]  Pad column width with minimum spaces and optional maximum truncate\n"
                L"  -             Use standard input for file\n");
        *code = 0;
        return true;
    }

    const wchar_t* opt_t = L"\n";
    const wchar_t* opt_s = L"";
    int min_pad = 0, max_pad = 0;
    FILE* files[64];
    int file_count = 0;

    for (int i = 1; i < cmd->argc; i++) {
        const wchar_t* arg = cmd->argv[i];
        if (wcscmp(arg, L"-t") == 0 && i + 1 < cmd->argc) opt_t = cmd->argv[++i];
        else if (wcscmp(arg, L"-s") == 0 && i + 1 < cmd->argc) opt_s = cmd->argv[++i];
        else if (wcscmp(arg, L"-p") == 0 && i + 1 < cmd->argc) {
            const wchar_t* p = cmd->argv[++i];
            min_pad = (int)wcstol(p, NULL, 10);
            const wchar_t* dot = wcschr(p, L'.');
            if (dot) max_pad = (int)wcstol(dot + 1, NULL, 10);
        } else {
            if (file_count < 64) {
                if (wcscmp(arg, L"-") == 0) files[file_count++] = stdin;
                else {
                    FILE* fp = _wfsopen(arg, L"rt, ccs=UTF-8", _SH_DENYNO);
                    if (!fp) fp = _wfsopen(arg, L"rt", _SH_DENYNO);
                    if (!fp) {
                        fwprintf(stderr, L"lam: %ls: No such file or directory\n", arg);
                        *code = 1;
                        return true;
                    }
                    files[file_count++] = fp;
                }
            }
        }
    }

    if (file_count == 0) {
        files[file_count++] = stdin;
    }

    wchar_t lineBuf[64][2048];
    bool active = true;
    while (active) {
        active = false;
        for (int i = 0; i < file_count; i++) {
            lineBuf[i][0] = L'\0';
            if (files[i] && fgetws(lineBuf[i], 2048, files[i])) {
                size_t l = wcslen(lineBuf[i]);
                while (l > 0 && (lineBuf[i][l - 1] == L'\r' || lineBuf[i][l - 1] == L'\n')) lineBuf[i][--l] = 0;
                active = true;
            }
        }
        if (!active) break;

        for (int i = 0; i < file_count; i++) {
            if (i > 0 && opt_s[0]) wprintf(L"%ls", opt_s);
            wchar_t* s = lineBuf[i];
            if (max_pad > 0 && (int)wcslen(s) > max_pad) s[max_pad] = 0;
            wprintf(L"%ls", s);
            if (min_pad > 0) {
                int pad = min_pad - (int)wcslen(s);
                while (pad-- > 0) putwchar(L' ');
            }
        }
        wprintf(L"%ls", opt_t);
    }

    for (int i = 0; i < file_count; i++) {
        if (files[i] && files[i] != stdin) fclose(files[i]);
    }
    *code = 0;
    return true;
}

/* ------------------------------------------------------------------------- */
/* 7. VMSTAT (BSD Virtual Memory & System Statistics)                       */
/* ------------------------------------------------------------------------- */

bool Builtin_Vmstat(CommandAST* cmd, int* code) {
    if (cmd->argc > 1 && (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: vmstat [-sw] [interval [count]]\n"
                L"Display virtual memory, paging, CPU, and performance counters.\n\n"
                L"  -s            Display summary memory statistics and system counters\n"
                L"  -w            Wide mode display\n"
                L"  interval      Update interval in seconds\n"
                L"  count         Number of times to report\n");
        *code = 0;
        return true;
    }

    bool opt_s = false, opt_w = false;
    int interval = 0, count = 1;

    for (int i = 1; i < cmd->argc; i++) {
        const wchar_t* arg = cmd->argv[i];
        if (wcscmp(arg, L"-s") == 0) opt_s = true;
        else if (wcscmp(arg, L"-w") == 0) opt_w = true;
        else if (interval == 0) interval = (int)wcstol(arg, NULL, 10);
        else count = (int)wcstol(arg, NULL, 10);
    }

    if (opt_s) {
        MEMORYSTATUSEX ms;
        memset(&ms, 0, sizeof(ms));
        ms.dwLength = sizeof(ms);
        GlobalMemoryStatusEx(&ms);
        PERFORMANCE_INFORMATION pi;
        memset(&pi, 0, sizeof(pi));
        pi.cb = sizeof(pi);
        GetPerformanceInfo(&pi, sizeof(pi));

        wprintf(L"%12llu K total physical memory\n", ms.ullTotalPhys / 1024);
        wprintf(L"%12llu K available physical memory\n", ms.ullAvailPhys / 1024);
        wprintf(L"%12llu K total page file\n", ms.ullTotalPageFile / 1024);
        wprintf(L"%12llu K available page file\n", ms.ullAvailPageFile / 1024);
        wprintf(L"%12llu K current commit total\n", (uint64_t)pi.CommitTotal * pi.PageSize / 1024);
        wprintf(L"%12llu K current commit limit\n", (uint64_t)pi.CommitLimit * pi.PageSize / 1024);
        wprintf(L"%12u processes\n", (unsigned int)pi.ProcessCount);
        wprintf(L"%12u threads\n", (unsigned int)pi.ThreadCount);
        wprintf(L"%12u system handles\n", (unsigned int)pi.HandleCount);
        wprintf(L"%12llu K kernel paged pool\n", (uint64_t)pi.KernelPaged * pi.PageSize / 1024);
        wprintf(L"%12llu K kernel non-paged pool\n", (uint64_t)pi.KernelNonpaged * pi.PageSize / 1024);
        *code = 0;
        return true;
    }

    (void)opt_w;
    wprintf(L" procs       memory               page                    cpu\n");
    wprintf(L" r  b   avm        fre        flt    re  pi  po    us  sy  id\n");

    FILETIME prev_idle, prev_kernel, prev_user;
    GetSystemTimes(&prev_idle, &prev_kernel, &prev_user);

    int iter = 0;
    while (true) {
        if (iter > 0 && interval > 0) Sleep(interval * 1000);

        MEMORYSTATUSEX ms;
        memset(&ms, 0, sizeof(ms));
        ms.dwLength = sizeof(ms);
        GlobalMemoryStatusEx(&ms);
        PERFORMANCE_INFORMATION pi;
        memset(&pi, 0, sizeof(pi));
        pi.cb = sizeof(pi);
        GetPerformanceInfo(&pi, sizeof(pi));

        FILETIME cur_idle, cur_kernel, cur_user;
        GetSystemTimes(&cur_idle, &cur_kernel, &cur_user);

        uint64_t idle = (((uint64_t)cur_idle.dwHighDateTime << 32) | cur_idle.dwLowDateTime) -
                        (((uint64_t)prev_idle.dwHighDateTime << 32) | prev_idle.dwLowDateTime);
        uint64_t kernel = (((uint64_t)cur_kernel.dwHighDateTime << 32) | cur_kernel.dwLowDateTime) -
                          (((uint64_t)prev_kernel.dwHighDateTime << 32) | prev_kernel.dwLowDateTime);
        uint64_t user = (((uint64_t)cur_user.dwHighDateTime << 32) | cur_user.dwLowDateTime) -
                        (((uint64_t)prev_user.dwHighDateTime << 32) | prev_user.dwLowDateTime);

        prev_idle = cur_idle;
        prev_kernel = cur_kernel;
        prev_user = cur_user;

        uint64_t total = kernel + user;
        int cpu_us = total > 0 ? (int)(user * 100 / total) : 0;
        int cpu_sy = total > 0 && kernel >= idle ? (int)((kernel - idle) * 100 / total) : 0;
        int cpu_id = total > 0 ? (int)(idle * 100 / total) : 100;
        if (cpu_id > 100) cpu_id = 100;

        uint64_t avm_m = ms.ullTotalPhys / (1024 * 1024);
        uint64_t fre_m = ms.ullAvailPhys / (1024 * 1024);

        wprintf(L" 1  0 %5lluM %9lluM     %5u     0   0   0   %3d %3d %3d\n",
                avm_m, fre_m, (unsigned int)(pi.HandleCount / 100), cpu_us, cpu_sy, cpu_id);

        iter++;
        if (count > 0 && iter >= count) break;
    }

    *code = 0;
    return true;
}

/* ------------------------------------------------------------------------- */
/* 8. PBCOPY (macOS / BSD Clipboard Copy)                                    */
/* ------------------------------------------------------------------------- */

static void GetClipFallbackPath(wchar_t* path, size_t cap) {
    wchar_t temp[MAX_PATH];
    if (GetTempPathW(MAX_PATH, temp)) {
        swprintf(path, cap, L"%lsntksh_clipboard.txt", temp);
    } else {
        wcsncpy(path, L"ntksh_clipboard.txt", cap);
    }
}

bool Builtin_Pbcopy(CommandAST* cmd, int* code) {
    if (cmd->argc > 1 && (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: pbcopy [-pboard {general|ruler|find|font}]\n"
                L"Read standard input and copy data to the Windows clipboard.\n");
        *code = 0;
        return true;
    }

    size_t cap = 8192;
    size_t len = 0;
    wchar_t* buf = (wchar_t*)malloc(cap * sizeof(wchar_t));
    if (!buf) { *code = 1; return true; }
    buf[0] = 0;

    wchar_t line_buf[4096];
    while (fgetws(line_buf, 4096, stdin)) {
        size_t l = wcslen(line_buf);
        if (len + l + 1 >= cap) {
            size_t newcap = (cap + l + 4096) * 2;
            wchar_t* newbuf = (wchar_t*)realloc(buf, newcap * sizeof(wchar_t));
            if (!newbuf) break;
            buf = newbuf;
            cap = newcap;
        }
        if (len + l + 1 < cap) {
            wmemcpy(buf + len, line_buf, l + 1);
            len += l;
        }
    }
    buf[len] = L'\0';

    wchar_t clipPath[MAX_PATH];
    GetClipFallbackPath(clipPath, MAX_PATH);
    FILE* fpClip = _wfsopen(clipPath, L"wt, ccs=UTF-8", _SH_DENYNO);
    if (fpClip) {
        fputws(buf, fpClip);
        fclose(fpClip);
    }

    if (OpenClipboard(NULL)) {
        EmptyClipboard();
        HGLOBAL hMem = GlobalAlloc(GMEM_MOVEABLE, (len + 1) * sizeof(wchar_t));
        if (hMem) {
            void* pMem = GlobalLock(hMem);
            if (pMem) {
                memcpy(pMem, buf, (len + 1) * sizeof(wchar_t));
                GlobalUnlock(hMem);
                if (!SetClipboardData(CF_UNICODETEXT, hMem)) {
                    GlobalFree(hMem);
                }
            } else {
                GlobalFree(hMem);
            }
        }
        CloseClipboard();
    }

    free(buf);
    *code = 0;
    return true;
}

/* ------------------------------------------------------------------------- */
/* 9. PBPASTE (macOS / BSD Clipboard Paste)                                  */
/* ------------------------------------------------------------------------- */

bool Builtin_Pbpaste(CommandAST* cmd, int* code) {
    if (cmd->argc > 1 && (_wcsicmp(cmd->argv[1], L"/?") == 0 || wcscmp(cmd->argv[1], L"--help") == 0)) {
        wprintf(L"Usage: pbpaste [-pboard {general|ruler|find|font}] [-Prefer {txt|rtf|ps}]\n"
                L"Print the contents of the Windows clipboard to standard output.\n");
        *code = 0;
        return true;
    }

    bool pasted = false;
    if (OpenClipboard(NULL)) {
        HANDLE hData = GetClipboardData(CF_UNICODETEXT);
        if (hData) {
            const wchar_t* pText = (const wchar_t*)GlobalLock(hData);
            if (pText) {
                if (*pText) {
                    fputws(pText, stdout);
                    fflush(stdout);
                }
                pasted = true;
                GlobalUnlock(hData);
            }
        }
        CloseClipboard();
    }

    if (!pasted) {
        wchar_t clipPath[MAX_PATH];
        GetClipFallbackPath(clipPath, MAX_PATH);
        FILE* fp = _wfsopen(clipPath, L"rt, ccs=UTF-8", _SH_DENYNO);
        if (fp) {
            wchar_t line[4096];
            while (fgetws(line, 4096, fp)) {
                fputws(line, stdout);
            }
            fclose(fp);
        }
    }

    *code = 0;
    return true;
}

